#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" is the breather between steps: it waits for Enter, unless --yes
# (YES=1) made pauses no-ops for a re-run.
pause() {
  [[ "${YES:-0}" == 1 ]] && return 0
  wait_for_user "$@"
}

# wait_for_user "msg" waits for the human to confirm they've done the manual
# part. Unlike pause, --yes never skips it: only the human can do that part.
wait_for_user() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# ── Wizard-specific helpers ───────────────────────────────────────────────
SCRIPT_PATH="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"
# Everything the wizard remembers between runs. The journal is append-only and
# spans all runs; backups/ holds each path as it was before the wizard ever
# touched it (first-ever-wins), mirroring its path relative to $HOME.
STATE_DIR="$HOME/.ghostty-herdr-wizard"
JOURNAL="$STATE_DIR/journal.tsv"
BACKUP_DIR="$STATE_DIR/backups"
# Where this run keeps a file it is about to replace when the store already has
# the original but the file has since changed (e.g. the user edited it).
REPLACED_DIR="$STATE_DIR/replaced/$(date +%Y%m%d-%H%M%S)"
# 1 while the stages run, so the helpers record what they change. Off when the
# library is only sourced (the tests turn it on themselves).
JOURNALING=0
# Answers saved from earlier runs, one KEY=value per line.
CHOICES="$STATE_DIR/choices.env"

# choice_get KEY: the saved answer for KEY, if there is one.
choice_get() {
  [[ -f "$CHOICES" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$CHOICES" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# choice_set KEY VALUE: save an answer so later runs (and --only) reuse it.
choice_set() {
  local tmp
  mkdir -p "$STATE_DIR"
  # Same directory as the target, so the mv is atomic.
  tmp=$(mktemp "$STATE_DIR/choices.XXXXXX")
  grep -vE "^${1}=" "$CHOICES" > "$tmp" 2>/dev/null || true
  printf '%s=%s\n' "$1" "$2" >> "$tmp"
  mv "$tmp" "$CHOICES"
}

# The Nerd Font switch: "on" puts file, folder and git icons everywhere; "off"
# gives every tool a plain-text look that works in any font. Asked in the
# choices stage, then followed by every config that could show a glyph.
GLYPHS=$(choice_get GLYPHS || true)
[[ "$GLYPHS" == off ]] || GLYPHS=on

# Colours for Ghostty, herdr, bat, Neovim and yazi: "auto" is Catppuccin Latte
# when macOS is light and Mocha when it's dark, "dark" is always Mocha, "none"
# writes no theme anywhere. Asked in the choices stage.
THEME=$(choice_get THEME || true)
case "$THEME" in dark|none) ;; *) THEME=auto ;; esac

# The starship prompt: "pure" or "tokyo" (see starship_config), or "none" to
# leave ~/.config/starship.toml alone. Asked in the choices stage.
PROMPT=$(choice_get PROMPT || true)
case "$PROMPT" in tokyo|none) ;; *) PROMPT=pure ;; esac

# The groups of tools the choices stage offers, each one checkbox: "key:title:
# stage". Tools are grouped only where they need each other. A declined group
# is neither installed nor configured, and a stage runs only when a group it
# configures is selected. Ghostty, herdr and terminal-notifier are not here:
# they are always installed. "icons" is the GLYPHS switch above.
CLUSTERS=(
  "icons:Nerd Font + icons:"
  "prompt:starship prompt:prompt"
  "jumper:project jumper + fuzzy find:shell"
  "typing:shell typing help:shell"
  "editor:editor:editor"
  "review:review the agent's diff:review"
  "files:file manager:yazi"
  "github:GitHub:github"
  "statusline:Claude Code status line:statusline"
)
RECOMMENDED_TOOLS="prompt,jumper,typing,editor,review,files,github,statusline"
# The selected groups other than icons, as ",a,b," for matching. Saved as the
# TOOLS choice; "none" means none of them.
TOOLS=$(choice_get TOOLS || true)
case "$TOOLS" in
  none) TOOLS="" ;;
  "") TOOLS="$RECOMMENDED_TOOLS" ;;
esac
TOOLS=",$TOOLS,"

# selected KEY: true if the group KEY is selected.
selected() {
  if [[ "$1" == icons ]]; then [[ "$GLYPHS" == on ]]; else [[ "$TOOLS" == *",$1,"* ]]; fi
}

# Homebrew lives in /opt/homebrew on Apple silicon and /usr/local on Intel. Put it
# on PATH for this run, so a terminal opened before installing brew still works.
# USER_PATH is the PATH from before that: the one the user's shells get, so the
# Node found on it is the one herdr-hunk will run on (see node_gate).
USER_PATH="$PATH"
BREW_BIN="$(command -v brew 2>/dev/null || true)"
for candidate in /opt/homebrew/bin/brew /usr/local/bin/brew; do
  if [[ -z "$BREW_BIN" && -x "$candidate" ]]; then BREW_BIN="$candidate"; fi
done
if [[ -n "$BREW_BIN" ]]; then eval "$("$BREW_BIN" shellenv)"; fi
BREW_PREFIX="$(brew --prefix 2>/dev/null || echo /opt/homebrew)"
GHOSTTY_BIN="/Applications/Ghostty.app/Contents/MacOS/ghostty"
HERDR_BIN="$BREW_PREFIX/bin/herdr"
LAUNCHER="$HOME/.local/bin/ghostty-launch"
CHEATSHEET="$HOME/.config/ghostty-herdr-cheatsheet.md"
STATUSLINE="$HOME/.claude/statusline.sh"
HERDR_CONFIG="$HOME/.config/herdr/config.toml"
HERDR_PLUGIN_DIR="$HOME/.herdr/plugins/worktree-tabs"
# herdr-hunk, the review group's hunk-by-hunk diff review, and the Node it needs
# (its package.json engines).
HUNK_ID="jhochenbaum.hunkdiff"
HUNK_REPO="jhochenbaum/herdr-hunk-diff"
NODE_MIN="22.12"
CHANGED=()   # files this run created or modified
BACKED_UP=() # paths this run copied into the backup store
KEPT=()      # changes --revert left alone because the user edited them since
WROTE=0      # set by install_file: 1 if its last call wrote the file

# Tabs opened on every new workspace and worktree, in order: agents, source
# code, local server, git review. Tab 4 opens the hunk review when herdr-hunk is
# installed. Saved as the TABS choice; "none" (DEFAULT_TABS empty) turns the
# plugin off.
SUGGESTED_TABS="agents,source code,local server,git review"
DEFAULT_TABS=$(choice_get TABS || true)
case "$DEFAULT_TABS" in
  none) DEFAULT_TABS="" ;;
  "") DEFAULT_TABS="$SUGGESTED_TABS" ;;
esac

ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
cmd() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; }

# ask_or_yes "question": confirm, except that --yes answers yes. Only for a
# question about the setup itself; a check of what the user sees, or replacing
# their file, still asks.
ask_or_yes() {
  [[ "$YES" == 1 ]] && return 0
  confirm "$1"
}

# run CMD...: show a command and run it. A failure is recorded for the closing
# summary instead of aborting, so one flaky install doesn't sink the rest.
run() {
  cmd "$*"
  if "$@"; then return 0; fi
  warn "failed: $*"
  SKIPPED+=("re-run manually: $*")
  return 0
}

# current_projects_dir: where the user keeps their repos. The choices stage's
# answer, else the one remembered in the wizard's ~/.zprofile block, else the
# first common folder that exists.
current_projects_dir() {
  local line candidate
  if line=$(choice_get PROJECTS_DIR) && [[ -n "$line" ]]; then
    printf '%s' "$line"
    return 0
  fi
  line=$(grep -E '^export PROJECTS_DIR=' "$HOME/.zprofile" 2>/dev/null | tail -1 || true)
  if [[ -n "$line" ]]; then
    line=${line#export PROJECTS_DIR=}
    line=${line#\"}
    line=${line%\"}
    printf '%s' "${line/\$HOME/$HOME}"
    return 0
  fi
  if [[ -n "${PROJECTS_DIR:-}" ]]; then
    printf '%s' "$PROJECTS_DIR"
    return 0
  fi
  for candidate in "$HOME/code" "$HOME/Code" "$HOME/projects" "$HOME/Projects" "$HOME/dev" "$HOME/src" "$HOME/Developer"; do
    if [[ -d "$candidate" ]]; then
      printf '%s' "$candidate"
      return 0
    fi
  done
  printf '%s' "$HOME/code"
}

in_ghostty() { [[ "${TERM_PROGRAM:-}" == "ghostty" || -n "${HERDR_ENV:-}" ]]; }

# brew_formulae NAME...: install only the formulae not already present.
# With --quiet first, say nothing when they are all there.
brew_formulae() {
  local missing quiet=false
  if [[ "${1:-}" == --quiet ]]; then quiet=true; shift; fi
  (( $# )) || return 0
  missing=$(missing_formulae "$@")
  if [[ -z "$missing" ]]; then
    $quiet || ok "already installed: $*"
  else
    # shellcheck disable=SC2086 # one formula per word
    run brew install $missing
  fi
}

# missing_formulae NAME...: the ones Homebrew doesn't have installed, one per line.
missing_formulae() {
  local installed f
  installed=" $(brew list --formula -1 2>/dev/null | tr '\n' ' ') "
  for f in "$@"; do
    [[ "$installed" == *" $f "* ]] || printf '%s\n' "$f"
  done
}

# ── Journal and backup store ──────────────────────────────────────────────
# journal.tsv, one tab-separated line per change, oldest first:
#   <time>  MODIFY   <path>  <backup ref>  <sha256 written, or "dir">
#   <time>  CREATE   <path>  <sha256 written, or "dir">
#   <time>  BLOCK    <path>  <comment leader>  <new|existing>  <sha256 written>
#   <time>  JSONKEY  <path>  <key>  <prior|<absent>>  <written|<absent>|<exists>>
#   <time>  GITKEY   <path>  <key>  <prior|<absent>>  <written>
#   <time>  MANUAL   <what to undo in System Settings>  <settings deep link>
#   <time>  PLUGIN   <herdr plugin id>  <new|pre-existing>
#   <time>  UNDO     <undo_ function --revert calls at the end>
# A backup ref is relative to $BACKUP_DIR. Lines are only ever appended.
#
# --revert undoes them newest first. It never deletes: whatever it takes away
# is moved under reverted/<time>/ (and --revert --restore moves it back). A
# file changed since the wizard wrote it is only reverted if the user says so.

journal_init() { mkdir -p "$BACKUP_DIR" && touch "$JOURNAL"; }

sha256() {
  if command -v shasum >/dev/null 2>&1; then shasum -a 256 "$1"; else sha256sum "$1"; fi | awk '{print $1}'
}

# backup_ref PATH: where PATH's backup lives, relative to $BACKUP_DIR.
backup_ref() {
  if [[ "$1" == "$HOME"/* ]]; then printf '%s' "${1#"$HOME"/}"; else printf '_root%s' "$1"; fi
}

# journal_entry PATH: PATH's most recent journal line, if it has one.
journal_entry() {
  [[ -f "$JOURNAL" ]] || return 1
  awk -F'\t' -v p="$1" '$3 == p { line = $0 } END { if (line == "") exit 1; print line }' "$JOURNAL"
}

# journal_append TYPE FIELD...: add one timestamped line to the journal.
journal_append() {
  journal_init
  local IFS=$'\t'
  printf '%s\t%s\n' "$(date +%Y-%m-%dT%H:%M:%S)" "$*" >> "$JOURNAL"
}

# journal_append_once TYPE KEY [FIELD...]: journal_append, unless a TYPE line
# for KEY is already there.
journal_append_once() {
  journal_init
  awk -F'\t' -v t="$1" -v k="$2" '$2 == t && $3 == k { found = 1 } END { exit !found }' "$JOURNAL" && return 0
  journal_append "$@"
}

# journal_write PATH EXISTED: record that the wizard just wrote PATH. EXISTED is
# true when a file was there before this write. A path keeps the type of its
# first entry: the wizard's own creation stays a CREATE however often it is
# rewritten, and a MODIFY keeps pointing at the user's original.
#
# A directory is hashed as "dir": it is undone as one unit, never drift-checked
# (moving it keeps everything in it), and it covers the entries inside it.
journal_write() {
  [[ "$JOURNALING" == 1 ]] || return 0
  local path="$1" existed="$2" prior type ref hash=dir
  [[ -f "$path" ]] && hash=$(sha256 "$path")
  journal_init
  if prior=$(journal_entry "$path"); then
    type=$(printf '%s' "$prior" | cut -f2)
  elif [[ "$existed" == true ]]; then
    type=MODIFY
  else
    type=CREATE
  fi
  # MODIFY carries the backup ref before the sha; CREATE has no backup.
  if [[ "$type" == MODIFY ]]; then
    journal_append MODIFY "$path" "$(backup_ref "$path")" "$hash"
  else
    journal_append "$type" "$path" "$hash"
  fi
}

# journal_manual DESCRIPTION LINK: record a change only System Settings can
# undo, as the step that undoes it and the settings pane where it's done.
# --revert prints these as a checklist; it never touches such settings itself.
journal_manual() {
  [[ "$JOURNALING" == 1 ]] || return 0
  journal_append_once MANUAL "$1" "$2"
}

# journal_plugin ID new|pre-existing: record a herdr plugin the wizard installed
# ("new") or found already there. --revert leaves plugins installed, like every
# tool; the entry tells a later --uninstall which ones are the wizard's.
journal_plugin() {
  [[ "$JOURNALING" == 1 ]] || return 0
  journal_append_once PLUGIN "$1" "$2"
}

# journal_undo FUNCTION: a stage with an effect no file entry expresses (herdr
# reloading its config) names the undo_<stage> function --revert calls once
# every file is back.
journal_undo() {
  [[ "$JOURNALING" == 1 ]] || return 0
  journal_append_once UNDO "$1"
}

# journaled_dirs: directories the journal records as created or replaced whole.
journaled_dirs() {
  [[ -f "$JOURNAL" ]] || return 0
  awk -F'\t' '($2 == "CREATE" || $2 == "MODIFY") && $NF == "dir" { print $3 }' "$JOURNAL"
}

# in_journaled_dir PATH: true when PATH lies inside one of journaled_dirs.
in_journaled_dir() {
  local dir
  while IFS= read -r dir; do
    [[ -n "$dir" && "$1" == "$dir"/* ]] && return 0
  done < <(journaled_dirs)
  return 1
}

# backup PATH: copy a file or directory into the backup store, but only the
# first time the wizard ever touches it. Later runs, and files the wizard
# created itself, are never captured there, so the store always holds what the
# user had before the wizard. When the store already has PATH but PATH is not
# byte-for-byte what the wizard last wrote (the user edited it since, or the
# stage doesn't journal), the current version goes to $REPLACED_DIR instead, so
# replacing it never loses anything.
backup() {
  [[ -e "$1" ]] || return 0
  # Inside a directory the wizard replaced whole: that directory is undone as
  # one unit, and a copy here would land inside the user's backed-up original.
  in_journaled_dir "$1" && return 0
  local ref prior=""
  ref=$(backup_ref "$1")
  prior=$(journal_entry "$1") || prior=""
  if [[ ! -e "$BACKUP_DIR/$ref" && -z "$prior" ]]; then
    mkdir -p "$(dirname "$BACKUP_DIR/$ref")"
    cp -Rp "$1" "$BACKUP_DIR/$ref"
    BACKED_UP+=("$1")
    note "backed up $1 → $BACKUP_DIR/$ref"
    return 0
  fi
  # Exactly what the wizard wrote last time: nothing of the user's to keep.
  if [[ -n "$prior" && -f "$1" && "${prior##*$'\t'}" == "$(sha256 "$1")" ]]; then
    return 0
  fi
  # Undone key by key, so the user's edits are never at risk: the first-ever
  # copy above is the whole safety net.
  case "$(printf '%s' "$prior" | cut -f2)" in JSONKEY | GITKEY) return 0 ;; esac
  [[ -e "$REPLACED_DIR/$ref" ]] && return 0
  mkdir -p "$(dirname "$REPLACED_DIR/$ref")"
  cp -Rp "$1" "$REPLACED_DIR/$ref"
  BACKED_UP+=("$1")
  note "kept the current $1 → $REPLACED_DIR/$ref"
}

# relocate PATH STAMP [LIST]: move PATH under reverted/STAMP/, keeping its path
# relative to $HOME, and list it there in LIST (default "manifest", the list
# --revert --restore puts back). The undo path never deletes anything; this is
# how it removes.
relocate() {
  local path="$1" stamp="$2" list="${3:-manifest}" dir aside
  dir="$STATE_DIR/reverted/$stamp"
  aside="$dir/$(backup_ref "$path")"
  mkdir -p "$(dirname "$aside")" || return 1
  mv "$path" "$aside" || return 1
  printf '%s\n' "$path" >> "$dir/$list"
}

# revert_drift_ok PATH SHA AFTER: whether to go ahead and revert PATH. SHA is
# what the wizard last wrote there. If PATH still matches it nobody touched it,
# so yes, silently. Otherwise the user edited it since: show the diff between
# PATH and AFTER (what reverting leaves there) and ask, defaulting to keeping
# their version, which is then listed in the closing summary.
revert_drift_ok() {
  local path="$1" want="$2" after="$3" have=""
  [[ "$want" == dir ]] && return 0
  [[ -f "$path" ]] && have=$(sha256 "$path")
  [[ "$have" == "$want" ]] && return 0
  printf '\n'
  warn "$path has changed since the wizard wrote it. Reverting would do this:"
  diff -u "$( [[ -f "$path" ]] && printf '%s' "$path" || printf /dev/null)" "$after" 2>/dev/null |
    head -40 | sed 's/^/    /' || true
  if confirm "Revert it anyway? (No keeps your version)"; then
    return 0
  fi
  KEPT+=("$path")
  return 1
}

# replace_dir DIR CMD...: give DIR a fresh start. An existing DIR is moved into
# the backup store (or this run's replaced folder, if the store already has
# the first-ever one), then CMD creates the new DIR, which is journaled as one
# unit so --revert moves the whole tree aside and puts the original back.
replace_dir() {
  local dir="$1" existed=false ref aside
  shift
  if [[ -e "$dir" ]]; then
    ref=$(backup_ref "$dir")
    aside="$BACKUP_DIR/$ref"
    [[ -e "$aside" ]] && aside="$REPLACED_DIR/$ref"
    mkdir -p "$(dirname "$aside")"
    mv "$dir" "$aside" || return 1
    existed=true
    BACKED_UP+=("$dir")
    note "moved $dir → $aside"
  fi
  "$@" || true
  # Journaled even if CMD failed, so the original can still be brought back.
  if [[ -e "$dir" ]] || $existed; then
    journal_write "$dir" "$existed"
    CHANGED+=("$dir")
  fi
  [[ -e "$dir" ]]
}

# restore_backup PATH REF STAMP: put the backup at REF back at PATH. The copy is
# staged next to PATH first, so a failed copy leaves PATH untouched; whatever
# was at PATH is relocated, never deleted.
restore_backup() {
  local path="$1" ref="$2" stamp="$3" staged
  [[ -e "$BACKUP_DIR/$ref" ]] || return 1
  staged="$path.ghostty-herdr-wizard-restore"
  mkdir -p "$(dirname "$path")"
  cp -Rp "$BACKUP_DIR/$ref" "$staged" || return 1
  if [[ -e "$path" ]]; then relocate "$path" "$stamp" || return 1; fi
  mv "$staged" "$path"
}

# revert_all: undo every journaled change, newest first. When all of it went
# back, archive the journal and the backups it used, so a later run starts
# clean. Backups taken by stages that don't journal yet stay in the store. If
# anything failed, nothing is archived and --revert can simply be run again.
revert_all() {
  if [[ ! -s "$JOURNAL" ]]; then
    say "Nothing to revert: the wizard has no record of changing anything on this machine."
    return 0
  fi
  local stamp seen=$'\n' refs=() manual=() hooks=() failed=0 type path f4 f5 f6 key archive ref_used
  stamp=$(revert_stamp)
  while IFS=$'\t' read -r -u 3 _ type path f4 f5 f6; do
    # Moving a directory the wizard created or replaced whole takes every
    # change inside it along, so those entries aren't undone one by one.
    in_journaled_dir "$path" && continue
    # Newest entry wins: one undo per path (per key, for key-level entries).
    key="$type $path $f4"
    case "$type" in MODIFY | CREATE | BLOCK) key="file $path" ;; esac
    case "$seen" in *$'\n'"$key"$'\n'*) continue ;; esac
    seen="$seen$key"$'\n'
    [[ -e "$BACKUP_DIR/$(backup_ref "$path")" ]] && refs+=("$(backup_ref "$path")")
    case "$type" in
      MODIFY) revert_modify "$path" "$f4" "$f5" "$stamp" ;;
      CREATE) revert_create "$path" "$f4" "$stamp" ;;
      BLOCK) revert_block "$path" "$f4" "$f5" "$stamp" ;;
      JSONKEY) revert_json_key "$path" "$f4" "$f5" "$f6" "$stamp" ;;
      GITKEY) revert_git_key "$f4" "$f5" "$f6" ;;
      MANUAL) manual=("$path"$'\t'"$f4" ${manual[@]+"${manual[@]}"}) ;;
      UNDO) hooks+=("$path") ;;
      # Tools stay installed on --revert; its config is what gets undone.
      PLUGIN) [[ "$f4" != new ]] || note "the herdr plugin $path stays installed (remove it: herdr plugin uninstall $path)" ;;
      *) warn "unrecognised journal entry '$type' for $path, skipped" ;;
    esac || failed=$((failed + 1))
  done 3< <(awk '{ line[NR] = $0 } END { for (i = NR; i > 0; i--) print line[i] }' "$JOURNAL")
  # Only names this script declares as undo_ functions: the journal is data.
  for key in ${hooks[@]+"${hooks[@]}"}; do
    if [[ "$key" =~ ^undo_[a-z_]+$ ]] && declare -F "$key" >/dev/null; then
      "$key" || failed=$((failed + 1))
    else
      warn "unknown undo step '$key' in the journal, skipped"
    fi
  done
  printf '\n'
  [[ -d "$STATE_DIR/reverted/$stamp" ]] && note "what the wizard left was moved to $STATE_DIR/reverted/$stamp"
  if (( ${#KEPT[@]} )); then
    printf '\n'; warn "kept your version of these, since you changed them after the wizard did:"
    for path in "${KEPT[@]}"; do note "  - $path"; done
  fi
  revert_checklist ${manual[@]+"${manual[@]}"}
  if (( failed )); then
    warn "$failed change(s) could not be undone; the journal is kept, so fix that and run --revert again"
    return 0
  fi
  archive="$STATE_DIR/archive/$stamp"
  mkdir -p "$archive"
  mv "$JOURNAL" "$archive/journal.tsv"
  for ref_used in ${refs[@]+"${refs[@]}"}; do
    [[ -e "$BACKUP_DIR/$ref_used" ]] || continue
    mkdir -p "$(dirname "$archive/backups/$ref_used")"
    mv "$BACKUP_DIR/$ref_used" "$archive/backups/$ref_used"
  done
  note "journal and the backups it used archived to $archive"
}

# revert_stamp: a name for this revert's folders, unique even within a second,
# that sorts after every earlier one.
revert_stamp() {
  local base stamp n=1
  base=$(date +%Y%m%d-%H%M%S)
  stamp="$base"
  while [[ -e "$STATE_DIR/reverted/$stamp" || -e "$STATE_DIR/archive/$stamp" ]]; do
    n=$((n + 1))
    stamp=$(printf '%s-%02d' "$base" "$n")
  done
  printf '%s' "$stamp"
}

# revert_restore: --revert --restore. Move everything the most recent revert
# relocated back to where it was, last moved first. Whatever is at such a path
# now is relocated first, listed as "in-the-way" so a second --restore doesn't
# swap it straight back; it stays under reverted/ like everything else.
revert_restore() {
  local dir="" candidate stamp path lines=() i failed=0
  # The newest folder a revert made (a restore's own "in-the-way" folders
  # don't count). Once that one is restored, there is nothing left to restore.
  for candidate in "$STATE_DIR"/reverted/*; do
    [[ -f "$candidate/manifest" || -f "$candidate/manifest.restored" ]] && dir="$candidate"
  done
  if [[ -z "$dir" || ! -f "$dir/manifest" ]]; then
    say "Nothing to restore: the last revert's changes are already back, or no revert moved anything."
    return 0
  fi
  stamp=$(revert_stamp)
  while IFS= read -r path; do lines+=("$path"); done < "$dir/manifest"
  for (( i = ${#lines[@]} - 1; i >= 0; i-- )); do
    path="${lines[$i]}"
    # Already put back by an earlier, partly failed --restore.
    [[ -e "$dir/$(backup_ref "$path")" ]] || continue
    if [[ -e "$path" ]] && ! relocate "$path" "$stamp" in-the-way; then
      warn "couldn't put back $path: couldn't move what's there now aside"
      failed=$((failed + 1))
      continue
    fi
    if mkdir -p "$(dirname "$path")" 2>/dev/null && mv "$dir/$(backup_ref "$path")" "$path"; then
      ok "put back $path"
    else
      warn "couldn't put back $path"
      failed=$((failed + 1))
    fi
  done
  [[ -d "$STATE_DIR/reverted/$stamp" ]] && note "what was in the way was moved to $STATE_DIR/reverted/$stamp"
  if (( failed )); then
    warn "$failed item(s) are still under $dir; fix that and run --revert --restore again"
    return 0
  fi
  mv "$dir/manifest" "$dir/manifest.restored"
}

# revert_checklist "DESCRIPTION<tab>LINK"...: the System Settings changes the
# user has to undo by hand, numbered, each offering to open its settings pane.
revert_checklist() {
  (( $# )) || return 0
  local i=0 item
  printf '\n'
  say "${BOLD}Left for you in System Settings${RESET} (the wizard never changes these itself):"
  for item in "$@"; do
    i=$((i + 1))
    say "$i. ${item%%$'\t'*}"
  done
  i=0
  for item in "$@"; do
    i=$((i + 1))
    confirm "Open the settings for $i now?" && open_url "${item#*$'\t'}"
  done
  return 0
}

# revert_modify PATH REF SHA STAMP: put the user's original back.
revert_modify() {
  local path="$1" ref="$2" hash="$3" stamp="$4"
  revert_drift_ok "$path" "$hash" "$BACKUP_DIR/$ref" || return 0
  if restore_backup "$path" "$ref" "$stamp"; then
    ok "restored $path"
    return 0
  fi
  warn "couldn't restore $path from $BACKUP_DIR/$ref, left as is"
  SKIPPED+=("restore $path from $BACKUP_DIR/$ref")
  return 1
}

# revert_create PATH SHA STAMP: move what the wizard created out of the way.
revert_create() {
  local path="$1" hash="$2" stamp="$3"
  if [[ ! -e "$path" ]]; then
    note "already gone: $path"
    return 0
  fi
  revert_drift_ok "$path" "$hash" /dev/null || return 0
  if relocate "$path" "$stamp"; then
    ok "moved $path (the wizard created it)"
    return 0
  fi
  warn "couldn't move $path aside, left as is"
  SKIPPED+=("move $path out of the way")
  return 1
}

# revert_key_ok LABEL CURRENT PRIOR WRITTEN: whether to set a key back to PRIOR.
# No if it already is. If it isn't what the wizard wrote either, the user
# changed it since: show both values and ask, defaulting to keeping theirs.
revert_key_ok() {
  local label="$1" current="$2" prior="$3" written="$4"
  [[ "$current" == "$prior" ]] && return 1
  [[ "$current" == "$written" ]] && return 0
  printf '\n'
  warn "$label has changed since the wizard set it."
  note "  now:            $current"
  note "  reverting sets: $prior"
  confirm "Revert it anyway? (No keeps your version)" && return 0
  KEPT+=("$label")
  return 1
}

# revert_json_key PATH KEY PRIOR WRITTEN STAMP: put one key back as it was, or
# delete it if it wasn't there. Nothing else in the file is touched. KEY []
# marks a file the wizard created: it is moved away once nothing else is in it.
revert_json_key() {
  local path="$1" key="$2" prior="$3" written="$4" stamp="$5" label current staged
  [[ -f "$path" ]] || return 0
  if [[ "$key" == '[]' ]]; then
    if jq -e '. == {}' "$path" >/dev/null 2>&1; then
      relocate "$path" "$stamp" || return 1
      ok "moved $path (the wizard created it)"
    else
      note "left $path in place: it holds other settings now"
    fi
    return 0
  fi
  label=$(jq -rn --argjson p "$key" '$p | join(".")')
  if ! current=$(jq -r --argjson p "$key" "$JQ_ENC"'enc(.; $p)' "$path" 2>/dev/null); then
    warn "$path isn't valid JSON, so $label couldn't be reverted"
    SKIPPED+=("revert $label in $path by hand")
    return 1
  fi
  revert_key_ok "$label in $path" "$current" "$prior" "$written" || return 0
  staged="$path.ghostty-herdr-wizard-restore"
  jq --argjson p "$key" --arg v "$prior" \
    'if $v == "<absent>" then delpaths([$p]) else setpath($p; $v | fromjson) end' "$path" > "$staged" &&
    mv "$staged" "$path" || return 1
  ok "reverted $label in $path"
}

# revert_git_key KEY PRIOR WRITTEN: put one global git setting back, or unset it.
revert_git_key() {
  local key="$1" prior="$2" written="$3"
  revert_key_ok "git $key" "$(git_global_value "$key")" "$prior" "$written" || return 0
  if [[ "$prior" == '<absent>' ]]; then
    git config --global --unset-all "$key" || return 1
  else
    git config --global "$key" "$prior" || return 1
  fi
  ok "reverted git $key"
}

# revert_block PATH LEADER ORIGIN STAMP: strip the wizard's block from PATH,
# whatever else changed in the file: the markers delimit it exactly. A file the
# wizard created just to hold the block, and nothing else, is moved away.
revert_block() {
  local path="$1" leader="$2" origin="$3" stamp="$4" staged
  if [[ ! -f "$path" ]] || ! grep -qxF -e "$(block_marker begin "$leader")" "$path"; then
    note "the wizard's block is already gone from $path"
    return 0
  fi
  if [[ "$origin" == new ]] && ! strip_block "$path" "$leader" | grep -q '[^[:space:]]'; then
    relocate "$path" "$stamp" || return 1
    ok "moved $path (the wizard created it for its block)"
    return 0
  fi
  staged="$path.ghostty-herdr-wizard-restore"
  strip_block "$path" "$leader" > "$staged" && mv "$staged" "$path" || return 1
  ok "removed the wizard's block from $path"
}

# install_file DEST < content: write DEST if it differs. An existing file that
# differs is shown as a diff and only replaced after confirmation, with a backup.
#
# Sets WROTE to 1 when it wrote DEST, 0 when it left DEST alone.
install_file() {
  local dest="$1" tmp existed=false
  WROTE=0
  tmp=$(mktemp)
  cat > "$tmp"
  if [[ -f "$dest" ]] && cmp -s "$tmp" "$dest"; then
    rm -f "$tmp"
    ok "unchanged: $dest"
    return 0
  fi
  if [[ -f "$dest" ]]; then
    existed=true
    warn "$dest already exists and differs:"
    diff -u "$dest" "$tmp" | head -40 | sed 's/^/    /' || true
    # content arrived on stdin, so the prompt must read the keyboard directly
    # (GHW_TTY lets the tests answer it from a file)
    if ! confirm "Replace it? (a backup is kept)" < "${GHW_TTY:-/dev/tty}"; then
      rm -f "$tmp"
      SKIPPED+=("left $dest unchanged")
      return 0
    fi
    backup "$dest"
  fi
  mkdir -p "$(dirname "$dest")"
  mv "$tmp" "$dest"
  journal_write "$dest" "$existed"
  WROTE=1
  CHANGED+=("$dest")
  ok "wrote $dest"
}

# track_file FILE CMD...: run CMD, a tool that may rewrite FILE itself (herdr's
# agent integrations do), and journal FILE like install_file would if it changed.
track_file() {
  local file="$1" existed=false before="" status=0
  shift
  if [[ -f "$file" ]]; then
    existed=true
    before=$(sha256 "$file")
    backup "$file"
  fi
  "$@" || status=$?
  if [[ -f "$file" && "$(sha256 "$file")" != "$before" ]]; then
    journal_write "$file" "$existed"
    CHANGED+=("$file")
  fi
  return "$status"
}

# upsert_block FILE [COMMENT] < content: replace (or append) the wizard-managed
# block in a config file, leaving everything outside the markers untouched.
# COMMENT is the file's comment leader: "#" (default) or "--" for Lua.
#
# Journaled as a BLOCK, not as a whole-file change: --revert strips just the
# markers' region, so everything the user keeps around it survives.
upsert_block() {
  local file="$1" leader="${2:-#}" body tmp origin=existing journaling="$JOURNALING"
  body=$(cat)
  tmp=$(mktemp)
  mkdir -p "$(dirname "$file")"
  [[ -e "$file" ]] || origin=new
  {
    [[ "$origin" == new ]] || strip_block "$file" "$leader"
    printf '%s\n%s\n%s\n' "$(block_marker begin "$leader")" "$body" "$(block_marker end "$leader")"
  } > "$tmp"
  JOURNALING=0
  install_file "$file" < "$tmp"
  JOURNALING="$journaling"
  rm -f "$tmp"
  (( WROTE )) && journal_block "$file" "$leader" "$origin"
  return 0
}

# block_marker begin|end LEADER: the line that opens or closes the wizard's block.
block_marker() {
  if [[ "$1" == begin ]]; then
    printf '%s >>> ghostty-herdr-wizard >>>' "$2"
  else
    printf '%s <<< ghostty-herdr-wizard <<<' "$2"
  fi
}

# strip_block FILE LEADER: FILE's content without the wizard's block.
strip_block() {
  awk -v b="$(block_marker begin "$2")" -v e="$(block_marker end "$2")" \
    '$0==b{skip=1;next} $0==e{skip=0;next} !skip' "$1"
}

# journal_block FILE LEADER ORIGIN: record the block just written. ORIGIN is
# "new" when the wizard created FILE to hold it; the first entry's wins.
journal_block() {
  [[ "$JOURNALING" == 1 ]] || return 0
  local prior
  if prior=$(journal_entry "$1") && [[ "$(printf '%s' "$prior" | cut -f2)" == BLOCK ]]; then
    set -- "$1" "$2" "$(printf '%s' "$prior" | cut -f5)"
  fi
  journal_append BLOCK "$1" "$2" "$3" "$(sha256 "$1")"
}

# ── Key-level JSON changes ────────────────────────────────────────────────
# ~/.claude/settings.json is shared with Claude Code, which writes to it as the
# user accepts permissions. So the wizard journals the exact keys it changed,
# each with its value from before the wizard first touched it:
#   <time>  JSONKEY  <path>  <key as a JSON path array>  <prior|<absent>>  <written|<absent>>
# and --revert undoes those keys alone. The file is still backed up once, as a
# safety net, but never restored whole. The key [] (prior <absent>, written
# <exists>) means the wizard created the file itself.

# enc(DOC; KEY): the value at KEY as compact JSON, or <absent>.
# shellcheck disable=SC2016
JQ_ENC='def enc($o; $p): if ($o | getpath($p[:-1]) | type) == "object" and ($o | getpath($p[:-1]) | has($p[-1]))
  then $o | getpath($p) | tojson else "<absent>" end;'

# json_track FILE CMD...: run CMD, which may change the JSON file FILE, and
# journal every key it changed (two levels deep, e.g. hooks.Stop).
json_track() {
  local file="$1" before after existed=true status=0
  shift
  [[ -f "$file" ]] || existed=false
  before='{}'
  if $existed && ! before=$(jq -c . "$file" 2>/dev/null); then
    warn "$file isn't valid JSON, so the wizard won't change it"
    SKIPPED+=("fix the JSON in $file, then re-run this stage")
    return 1
  fi
  backup "$file"
  "$@" || status=$?
  after='{}'
  [[ -f "$file" ]] && after=$(jq -c . "$file" 2>/dev/null || printf '{}')
  if [[ "$before" != "$after" ]]; then
    CHANGED+=("$file")
    $existed || journal_key JSONKEY "$file" '[]' '<absent>' '<exists>'
    local key prior written
    while IFS=$'\t' read -r key prior written; do
      journal_key JSONKEY "$file" "$key" "$prior" "$written"
    done < <(json_changes "$before" "$after")
  fi
  return "$status"
}

# json_set FILE FILTER [JQ ARGS...]: rewrite FILE through a jq filter, creating
# it as {} first if needed, and journal the keys that changed.
json_set() {
  local file="$1"
  shift
  json_track "$file" _json_apply "$file" "$@"
}

# _json_apply FILE FILTER [JQ ARGS...]: json_set's write, run under json_track.
_json_apply() {
  local file="$1" tmp
  shift
  tmp=$(mktemp)
  mkdir -p "$(dirname "$file")"
  [[ -f "$file" ]] || printf '{}\n' > "$file"
  if jq "$@" "$file" > "$tmp"; then
    mv "$tmp" "$file"
    ok "updated $file"
  else
    rm -f "$tmp"
    return 1
  fi
}

# json_changes BEFORE AFTER: one line per changed key, "<key> <prior> <written>",
# values compact JSON or <absent>. Objects are compared one level down, so a
# tool adding hooks.Stop doesn't claim the user's other hooks.
json_changes() {
  jq -rn --argjson a "$1" --argjson b "$2" "$JQ_ENC"'
    ((($a | keys_unsorted) + ($b | keys_unsorted)) | unique[]) as $k
    | (if ($a[$k] | type) == "object" and ($b[$k] | type) == "object"
       then ((($a[$k] | keys_unsorted) + ($b[$k] | keys_unsorted)) | unique[]) as $k2 | [$k, $k2]
       else [$k] end) as $p
    | select(enc($a; $p) != enc($b; $p))
    | [($p | tojson), enc($a; $p), enc($b; $p)] | join("\t")'
}

# journal_key TYPE FILE KEY PRIOR WRITTEN: append a JSONKEY or GITKEY entry. A
# key the journal already knows keeps its first-ever prior value.
journal_key() {
  [[ "$JOURNALING" == 1 ]] || return 0
  local first
  journal_init
  first=$(awk -F'\t' -v t="$1" -v p="$2" -v k="$3" '$2 == t && $3 == p && $4 == k { print $5; exit }' "$JOURNAL")
  [[ -n "$first" ]] && set -- "$1" "$2" "$3" "$first" "$5"
  journal_append "$@"
}

# git_global_value KEY: KEY's global git value, or <absent>.
git_global_value() {
  git config --global --get "$1" 2>/dev/null || printf '<absent>'
}

# git_set KEY VALUE: set a global git config value if it isn't already. No
# stage sets git config any more, but journals from earlier versions hold
# GITKEY entries, and this is the writer --revert's handling of them is
# tested against.
# Journaled key by key like the JSON settings, since the user edits their git
# config too:  <time>  GITKEY  ~/.gitconfig  <key>  <prior|<absent>>  <written>
git_set() {
  local prior
  prior=$(git_global_value "$1")
  if [[ "$prior" == "$2" ]]; then
    ok "git $1 = $2"
    return 0
  fi
  run git config --global "$1" "$2"
  [[ "$(git_global_value "$1")" == "$2" ]] && journal_key GITKEY "$HOME/.gitconfig" "$1" "$prior" "$2"
  return 0
}

# ctrl_space_taken: true while macOS still claims Ctrl-Space for input sources.
ctrl_space_taken() {
  local v
  v=$(/usr/libexec/PlistBuddy -c "Print :AppleSymbolicHotKeys:60:enabled" \
    "$HOME/Library/Preferences/com.apple.symbolichotkeys.plist" 2>/dev/null || echo missing)
  [[ "$v" != "false" ]]
}

# herdr_integration_current AGENT: true when herdr's hook for AGENT is up to date.
herdr_integration_current() {
  herdr integration status 2>/dev/null | grep "^$1: current" >/dev/null
}

# ghostty_config [autostart]: the full Ghostty config. "autostart" makes every
# new window go through ghostty-launch, which decides between herdr and a shell.
ghostty_config() {
  cat <<'EOF'
# Ghostty config, written by ghostty-herdr-wizard.sh
# Reference: https://ghostty.org/docs/config/reference
# Reload after editing: Cmd-Shift-,

# ── Font ──────────────────────────────────────────────
EOF
  if [[ "$GLYPHS" == on ]]; then
    printf 'font-family = JetBrainsMono Nerd Font\n'
  else
    printf "# Ghostty's built-in JetBrains Mono: icons are switched off.\n"
  fi
  cat <<'EOF'
font-size = 14

# ── Look ──────────────────────────────────────────────
EOF
  case "$THEME" in
    auto) printf '%s\n' "# Follows macOS light/dark, same palettes as herdr, nvim, bat and yazi." \
      "theme = light:Catppuccin Latte,dark:Catppuccin Mocha" ;;
    dark) printf '%s\n' "# Always dark, same palette as herdr, nvim, bat and yazi." \
      "theme = Catppuccin Mocha" ;;
  esac
  cat <<'EOF'
window-padding-x = 10
window-padding-y = 8
window-padding-balance = true
macos-titlebar-style = transparent
cursor-style-blink = false
mouse-hide-while-typing = true

# ── Behaviour ─────────────────────────────────────────
# Left Option acts as Alt (Alt shortcuts in herdr, nvim, fzf Alt-C).
# Right Option still types special characters.
macos-option-as-alt = left
copy-on-select = clipboard
# herdr keeps sessions alive, so closing a window never loses work.
confirm-close-surface = false
desktop-notifications = true
shell-integration-features = ssh-terminfo,ssh-env
auto-update = check

# ── Quick terminal: Ctrl-` from any app ───────────────
quick-terminal-position = top
quick-terminal-autohide = true
keybind = global:ctrl+backquote=toggle_quick_terminal

# ── herdr shortcuts ───────────────────────────────────
# Each sends herdr's prefix (Ctrl-Space is byte \x00) and then a herdr key,
# so they only do something inside herdr.
keybind = cmd+d=text:\x00v
keybind = cmd+shift+d=text:\x00-
keybind = cmd+t=text:\x00c
keybind = cmd+p=text:\x00g
EOF
  # The popups herdr only has for selected tools (see herdr_config).
  selected jumper && printf '%s\n' 'keybind = cmd+o=text:\x00m'
  selected files && printf '%s\n' 'keybind = cmd+e=text:\x00f'
  selected review && printf '%s\n' 'keybind = cmd+shift+g=text:\x00d'
  cat <<'EOF'
keybind = cmd+shift+enter=text:\x00z
# Both spellings of [ and ]: Ghostty's own cmd+shift+[ / ] switch Ghostty tabs.
keybind = cmd+shift+bracket_left=text:\x00,
keybind = cmd+shift+bracket_right=text:\x00.
keybind = cmd+shift+[=text:\x00,
keybind = cmd+shift+]=text:\x00.
# digit_N is the physical key. Ghostty's built-in cmd+digit_N=goto_tab wins over
# a plain cmd+N binding, so herdr tab switching has to use the same key name.
keybind = cmd+digit_1=text:\x001
keybind = cmd+digit_2=text:\x002
keybind = cmd+digit_3=text:\x003
keybind = cmd+digit_4=text:\x004
keybind = cmd+digit_5=text:\x005
keybind = cmd+digit_6=text:\x006
keybind = cmd+digit_7=text:\x007
keybind = cmd+digit_8=text:\x008
keybind = cmd+digit_9=text:\x009
EOF
  if [[ "${1:-}" == "autostart" ]]; then
    cat <<EOF

# ── herdr in every new window ─────────────────────────
# ghostty-launch attaches herdr unless herdr is already open in another window,
# in which case you get a plain shell (so Cmd-N is the "no herdr" shortcut).
# Delete this line to go back to plain shells everywhere.
command = direct:$LAUNCHER
EOF
  fi
}

install_launcher() {
  install_file "$LAUNCHER" <<'EOF'
#!/bin/zsh
# ghostty-launch: Ghostty runs this for every new window, tab and the quick terminal.
# Written by ghostty-herdr-wizard.sh.
#
#   herdr not open in any window    → attach herdr (opening Ghostty lands you in herdr)
#   herdr already open elsewhere    → plain shell (Cmd-N is the "without herdr" shortcut)
#   you detach herdr (Ctrl-Space q) → this window carries on as a plain shell
#   GHOSTTY_NO_HERDR=1 is set       → always a plain shell
# Ghostty starts this with macOS's minimal PATH. herdr needs Homebrew's, e.g. to
# find terminal-notifier for desktop notifications.
export PATH="/opt/homebrew/bin:/opt/homebrew/sbin:/usr/local/bin:$PATH"

herdr_bin=""
for candidate in /opt/homebrew/bin/herdr /usr/local/bin/herdr "$HOME/.local/bin/herdr"; do
  if [[ -x "$candidate" ]]; then herdr_bin="$candidate"; break; fi
done

# A herdr client's command line is just ".../herdr"; the background server is "herdr server".
if [[ -n "$herdr_bin" && -z "${GHOSTTY_NO_HERDR:-}" ]] && ! pgrep -f '(^|/)herdr$' >/dev/null 2>&1; then
  "$herdr_bin"
fi
exec "${SHELL:-/bin/zsh}" -l
EOF
  chmod +x "$LAUNCHER"
}

# write_ghostty_config: the Ghostty config, with herdr auto-start once herdr exists.
write_ghostty_config() {
  if [[ -x "$HERDR_BIN" ]]; then
    install_launcher
    install_file "$HOME/.config/ghostty/config" < <(ghostty_config autostart)
  else
    install_file "$HOME/.config/ghostty/config" < <(ghostty_config)
  fi
  if "$GHOSTTY_BIN" +validate-config; then
    ok "Ghostty config is valid"
  else
    warn "Ghostty reported config problems (above)"
    SKIPPED+=("fix Ghostty config errors: $GHOSTTY_BIN +validate-config")
  fi
}

# prompt_style: the starship config stage_prompt writes: PROMPT, except that
# Tokyo Night needs the Nerd Font, so with the glyph switch off it's Pure.
prompt_style() {
  if [[ "$PROMPT" == tokyo && "$GLYPHS" != on ]]; then echo pure; else echo "$PROMPT"; fi
}

# starship_config [STYLE]: a hand-written starship.toml for STYLE (default:
# prompt_style) showing just the folder and the git branch. Upstream presets
# carry a dozen modules and change as starship does, so neither is built from one.
#   pure   Pure-style, plain text, so it works in any font
#   tokyo  Tokyo Night-style powerline segments, needs the Nerd Font
# Segment text has at least 5:1 contrast with its background (WCAG AA is 4.5).
starship_config() {
  local folder=$'\xef\x81\xbb' branch=$'\xee\x9c\xa5' sep=$'\xee\x82\xb0'
  case "${1:-$(prompt_style)}" in
    pure) cat <<'EOF'
# Pure-style prompt, written by ghostty-herdr-wizard.sh: the folder and the git
# branch, then ❯ on its own line. Plain text, so any font works.
# Reference: https://starship.rs/config
format = """
$directory$git_branch
$character"""

[directory]
style = "blue"
truncation_length = 3
truncation_symbol = "…/"
truncate_to_repo = false
read_only = " ro"

[git_branch]
format = "[$branch]($style) "
style = "bright-black"

[character]
success_symbol = "[❯](purple)"
error_symbol = "[❯](red)"
vimcmd_symbol = "[❮](green)"
EOF
      ;;
    tokyo) cat <<EOF
# Tokyo Night-style prompt, written by ghostty-herdr-wizard.sh: the folder and
# the git branch on powerline segments. Needs a Nerd Font.
# Reference: https://starship.rs/config
format = "\$directory\$git_branch"

[directory]
style = "fg:#1a1b26 bg:#769ff0"
format = "[ $folder \$path ](\$style)[$sep](fg:#769ff0) "
truncation_length = 3
truncation_symbol = "…/"
truncate_to_repo = false
read_only = " ro"

[git_branch]
symbol = "$branch"
style = "fg:#c0caf5 bg:#394260"
format = "[ \$symbol \$branch ](\$style)[$sep](fg:#394260) "
EOF
      ;;
  esac
}

# prompt_preview STYLE: STYLE's prompt as it looks in this folder. starship
# draws it when installed; before that (the choices stage runs before the
# install stage) it's drawn here, to the same design.
prompt_preview() {
  # bash 3.2 keeps the backslash of a quoted \~ replacement, so ~ goes in a variable.
  local tmp out="" here branch tilde='~'
  if command -v starship >/dev/null 2>&1; then
    tmp=$(mktemp "${TMPDIR:-/tmp}/ghw-starship.XXXXXX")
    starship_config "$1" > "$tmp"
    # bash's \[ \] markers around colour codes would print as text.
    out=$(STARSHIP_CONFIG="$tmp" STARSHIP_SHELL=bash starship prompt 2>/dev/null |
      sed 's/\\\[//g; s/\\\]//g' | grep -v '^[[:space:]]*$') || true
    rm -f "$tmp"
  fi
  if [[ -n "$out" ]]; then
    sed 's/^/     /' <<<"$out"
    printf '%s' "$RESET"
    return 0
  fi
  # The last three folders, as starship's truncation_length = 3 shows them.
  here=$(awk -F/ '{ n = NF - ($1 == ""); if (n > 3) print "…/" $(NF-2) "/" $(NF-1) "/" $NF; else print }' \
    <<<"${PWD/#$HOME/$tilde}")
  branch=$(git branch --show-current 2>/dev/null || true)
  case "$1" in
    pure)
      printf '     %s%s%s%s\n' "$BLUE" "$here" "$RESET" "${branch:+ $DIM$branch$RESET}"
      printf '     %s❯%s\n' "$BOLD" "$RESET"
      ;;
    tokyo)
      local dir_bg="" git_bg="" dir_end="" git_end=""
      if [[ -n "$RESET" ]]; then
        dir_bg=$'\033[38;2;26;27;38;48;2;118;159;240m' dir_end=$'\033[0;38;2;118;159;240m'
        git_bg=$'\033[38;2;192;202;245;48;2;57;66;96m' git_end=$'\033[0;38;2;57;66;96m'
      fi
      printf '     %s %s %s %s%s%s' "$dir_bg" $'\xef\x81\xbb' "$here" "$dir_end" $'\xee\x82\xb0' "$RESET"
      [[ -n "$branch" ]] && printf ' %s %s %s %s%s%s' "$git_bg" $'\xee\x9c\xa5' "$branch" "$git_end" $'\xee\x82\xb0' "$RESET"
      printf '\n'
      ;;
  esac
}

statusline_script() {
  cat <<'EOF'
#!/bin/bash
# Claude Code status line, written by ghostty-herdr-wizard.sh
# Docs: https://code.claude.com/docs/en/statusline
#
# Line 1: model · effort │ directory │ worktree (only inside a linked git worktree)
# Line 2: context used │ session cost │ 5-hour limit │ weekly limit (limits: Pro/Max only)

input=$(cat)

# One jq call. Fields are joined with the ASCII unit separator, not tabs:
# `read` merges consecutive tabs, which would shift fields left when one is empty.
IFS=$'\x1f' read -r model dir worktree cost ctx_pct ctx_tokens ctx_size effort \
  five_pct five_reset week_pct <<<"$(jq -r '[
    .model.display_name // "Claude",
    .workspace.current_dir // .cwd // "",
    .workspace.git_worktree // "",
    .cost.total_cost_usd // 0,
    .context_window.used_percentage // "",
    .context_window.total_input_tokens // 0,
    .context_window.context_window_size // 0,
    .effort.level // "",
    .rate_limits.five_hour.used_percentage // "",
    .rate_limits.five_hour.resets_at // "",
    .rate_limits.seven_day.used_percentage // ""
  ] | map(tostring) | join("\u001f")' <<<"$input")"

# Catppuccin Mocha
rgb()   { printf '\033[38;2;%sm' "$1"; }
MAUVE=$(rgb "203;166;247"); BLUE=$(rgb "137;180;250"); TEAL=$(rgb "148;226;213")
GREEN=$(rgb "166;227;161"); YELLOW=$(rgb "249;226;175"); RED=$(rgb "243;139;168")
PEACH=$(rgb "250;179;135"); DIM=$(rgb "127;132;156"); RESET=$'\033[0m'
SEP=" ${DIM}│${RESET} "

EOF
  if [[ "$GLYPHS" == on ]]; then
    cat <<'EOF'
# Nerd Font icons. Set them to "" for plain text.
ICON_MODEL=$'\xf3\xb0\x9a\xa9'  # nf-md-robot
ICON_DIR=$'\xef\x81\xbb'        # nf-fa-folder
ICON_BRANCH=$'\xee\x9c\xa5'     # nf-dev-git_branch
EOF
  else
    cat <<'EOF'
# Plain text: no Nerd Font. Re-run the wizard with icons on to fill these in.
ICON_MODEL=""
ICON_DIR=""
ICON_BRANCH=""
EOF
  fi
  cat <<'EOF'

# pct_color N: green under 50, yellow under 80, red from 80
pct_color() {
  local p=${1%.*}
  if (( p >= 80 )); then printf '%s' "$RED"
  elif (( p >= 50 )); then printf '%s' "$YELLOW"
  else printf '%s' "$GREEN"; fi
}

# pct LABEL VALUE [SUFFIX]: "label 23%" with the number coloured by severity
pct() {
  local rounded
  rounded=$(printf '%.0f' "$2")
  printf '%s%s%s %s%s%%%s%s' "$DIM" "$1" "$RESET" "$(pct_color "$rounded")" "$rounded" "$RESET" "${3:-}"
}

# tokens N: 950 → 950, 46500 → 47k, 1200000 → 1.2M
tokens() {
  awk -v n="$1" 'BEGIN { if (n >= 1000000) printf "%.1fM", n / 1000000; else if (n >= 1000) printf "%.0fk", n / 1000; else printf "%d", n }'
}

# Directory: ~ for home, then only the last three segments
if [[ "$dir" == "$HOME"* ]]; then dir="~${dir#"$HOME"}"; fi
dir=$(awk -F/ '{ if (NF > 4) printf "…/%s/%s/%s", $(NF-2), $(NF-1), $NF; else printf "%s", $0 }' <<<"$dir")

line1="${MAUVE}${ICON_MODEL:+$ICON_MODEL }${model}${RESET}"
if [[ -n "$effort" ]]; then line1+=" ${DIM}effort${RESET} ${PEACH}${effort}${RESET}"; fi
line1+="${SEP}${BLUE}${ICON_DIR:+$ICON_DIR }${dir}${RESET}"
if [[ -n "$worktree" ]]; then line1+="${SEP}${TEAL}${ICON_BRANCH:+$ICON_BRANCH }worktree ${worktree}${RESET}"; fi

if [[ -n "$ctx_pct" ]]; then
  line2="$(pct context "$ctx_pct") ${DIM}($(tokens "$ctx_tokens")/$(tokens "$ctx_size") tokens)${RESET}"
else
  line2="${DIM}context –${RESET}"
fi
line2+="${SEP}${GREEN}$(printf '$%.2f' "$cost")${RESET} ${DIM}session${RESET}"
if [[ -n "$five_pct" ]]; then
  reset_note=""
  if [[ -n "$five_reset" ]]; then reset_note=" ${DIM}resets $(date -r "$five_reset" +%H:%M)${RESET}"; fi
  line2+="${SEP}$(pct "5h limit" "$five_pct" "$reset_note")"
fi
if [[ -n "$week_pct" ]]; then line2+="${SEP}$(pct "week limit" "$week_pct")"; fi

printf '%s\n%s\n' "$line1" "$line2"
EOF
}

statusline_configured() {
  [[ -f "$HOME/.claude/settings.json" ]] &&
    jq -e --arg cmd "$STATUSLINE" '.statusLine.command == $cmd' "$HOME/.claude/settings.json" >/dev/null 2>&1
}

# ── Stages ────────────────────────────────────────────────────────────────

# preflight: stop before any stage on a machine the wizard can't set up.
preflight() {
  if [[ "$(uname -s)" != "Darwin" ]]; then
    warn "This wizard targets macOS (Ghostty, Homebrew casks, macOS settings)."
    exit 1
  fi
  if ! command -v brew >/dev/null 2>&1; then
    warn "Homebrew not found. Install it from https://brew.sh and re-run."
    exit 1
  fi
}

# ── Node, for herdr-hunk ──────────────────────────────────────────────────
# herdr-hunk needs Node $NODE_MIN or newer. The wizard only ever checks it:
# Node is usually run by a version manager (nvm, fnm, volta, asdf, mise), a
# Homebrew Node next to one fights it on PATH, upgrading breaks projects pinned
# to an older one, and --revert could undo none of that. So an old Node greys
# herdr-hunk out and names the command for the manager that installed it.

# Every check looks at the user's own PATH, not the wizard's, which has
# Homebrew put first: a Homebrew Node there may not be the one their shells run.

# node_path: where the user's Node is. Fails if they have none.
node_path() { (PATH="$USER_PATH"; command -v node); }

# node_version: the user's Node version, e.g. v20.19.2. Fails if there is none.
node_version() {
  local node v
  node=$(node_path) && v=$("$node" --version 2>/dev/null) && [[ "$v" =~ ^v[0-9]+\.[0-9]+ ]] || return 1
  printf '%s' "$v"
}

# node_ok: true if the user's Node is new enough for herdr-hunk.
node_ok() {
  local v major minor
  v=$(node_version) || return 1
  v=${v#v}
  major=${v%%.*}
  minor=${v#*.}
  minor=${minor%%.*}
  (( 10#$major > ${NODE_MIN%.*} || (10#$major == ${NODE_MIN%.*} && 10#$minor >= ${NODE_MIN#*.}) ))
}

# node_manager: what put the Node on PATH there, going by where it lives:
# nvm, fnm, volta, asdf, mise or "Homebrew <formula>". Empty if unknown.
node_manager() {
  local path target formula
  path=$(node_path) || return 0
  case "$path" in
    */.nvm/*) echo nvm ;;
    */fnm/* | */fnm_multishells/*) echo fnm ;;
    */.volta/*) echo volta ;;
    */.asdf/*) echo asdf ;;
    */mise/*) echo mise ;;
    "$BREW_PREFIX"/opt/*/bin/node)
      formula=${path#"$BREW_PREFIX"/opt/}
      echo "Homebrew ${formula%%/*}"
      ;;
    "$BREW_PREFIX"/*)
      # Homebrew's links into its Cellar: ../Cellar/<formula>/<version>/bin/node.
      # Anything else there (the nodejs.org installer uses /usr/local) isn't brew's.
      target=$(readlink "$path" 2>/dev/null || true)
      if [[ "$target" == *Cellar/* ]]; then
        formula=${target#*Cellar/}
        echo "Homebrew ${formula%%/*}"
      fi
      ;;
  esac
}

# node_fix MANAGER: the command that gets MANAGER to a Node new enough for
# herdr-hunk, and makes it the one new shells (and so herdr) get. Printed for
# the user to run, never run by the wizard.
node_fix() {
  case "$1" in
    nvm) echo "nvm install 22 && nvm use 22 && nvm alias default 22" ;;
    fnm) echo "fnm install 22 && fnm default 22" ;;
    volta) echo "volta install node@22" ;;
    asdf) echo "asdf install nodejs latest:22 && asdf set -u nodejs latest:22" ;;
    mise) echo "mise use -g node@22" ;;
    "Homebrew node" | "Homebrew node@22") echo "brew upgrade ${1#Homebrew }" ;;
    "Homebrew "*) echo "brew install node@22, then put $BREW_PREFIX/opt/node@22/bin on PATH in place of ${1#Homebrew }" ;;
    *) echo "install Node $NODE_MIN or newer: https://nodejs.org, or a manager such as nvm" ;;
  esac
}

# node_gate: true, silently, if Node is new enough for herdr-hunk. Otherwise
# prints why not (the Node found and who manages it) and the command to fix it,
# and fails.
node_gate() {
  node_ok && return 0
  local v manager=""
  if v=$(node_version); then
    manager=$(node_manager)
    printf 'needs Node %s+, you have %s%s\n' "$NODE_MIN" "$v" "${manager:+ (via $manager)}"
  else
    printf 'needs Node %s+, none found\n' "$NODE_MIN"
  fi
  printf '  %s\n' "$(node_fix "$manager")"
  return 1
}

# hunk_tools: the review group's herdr-hunk line(s) for the selection screen.
# Greyed out, with the fix, while Node is too old.
hunk_tools() {
  local gate line
  if gate=$(node_gate); then
    printf '%s\n' "herdr-hunk|review the agent's diff hunk by hunk, comment, send it back to the agent"
    return 0
  fi
  printf '%s\n' "herdr-hunk|${DIM}needs newer Node${RESET}"
  printf '%s\n' "|${DIM}review the agent's diff hunk by hunk, comment, send it back.${RESET}"
  while IFS= read -r line; do
    printf '|%s%s%s\n' "$DIM" "$line" "$RESET"
  done <<< "$gate"
  printf '|%sthen: bash %s --only review%s\n' "$DIM" "$SCRIPT_PATH" "$RESET"
  printf '|%stab 4 stays a plain shell for now%s\n' "$DIM" "$RESET"
}

# cluster_tools KEY: what the group KEY brings, one "tool|what it gives you"
# per line, as the selection screen lists it.
cluster_tools() {
  case "$1" in
    icons) printf '%s\n' "Nerd Font|JetBrains Mono Nerd Font, unless you have it: file, folder and git" \
      "|icons in the prompt, ls, yazi, Neovim, lazygit, herdr and the status line." \
      "|Unticked: plain text that works in any font (e.g. iTerm), no font install" ;;
    prompt) printf '%s\n' "starship|a prompt showing the folder and git branch, in the style you pick" ;;
    jumper) printf '%s\n' "fzf|fuzzy search: Ctrl-R history, Ctrl-T files, and the project picker" \
      "fd|fast file finder behind that search" \
      "eza|ls with git status and a tree view" \
      "bat|cat with syntax highlighting, and fzf's file preview" ;;
    typing) printf '%s\n' "zsh-autosuggestions|suggests the rest of a command from your history" \
      "zsh-syntax-highlighting|colours a command red before you run it if it's wrong" ;;
    editor) printf '%s\n' "neovim|the editor, opened next to your agent" \
      "LazyVim|a ready-made Neovim setup: file tree, search, git signs" \
      "tree-sitter-cli|builds the syntax parsers LazyVim uses" \
      "ripgrep|fast search inside files, for LazyVim's grep" \
      "fd|fast file finder, for LazyVim's file picker" ;;
    review) hunk_tools
      printf '%s\n' "lazygit|a git UI: stage single lines or hunks, commit, branch, rebase" ;;
    files) printf '%s\n' "yazi|a file manager in the terminal, with previews" \
      "poppler|lets yazi preview PDFs" \
      "resvg|lets yazi preview SVG images" ;;
    github) printf '%s\n' "gh|the GitHub CLI: sign in, clone, open PRs" \
      "gh-dash|your PRs, review requests and issues in one screen" ;;
    statusline) printf '%s\n' "status line|context used, cost and rate limits under Claude Code's prompt" ;;
  esac
}

# show_clusters: the selection screen's numbered checkboxes.
show_clusters() {
  local entry key i=0 tool what box
  for entry in "${CLUSTERS[@]}"; do
    i=$((i + 1))
    key=${entry%%:*}
    if selected "$key"; then box="[x]"; else box="[ ]"; fi
    entry=${entry#*:}
    say "$i $box ${entry%%:*}"
    while IFS='|' read -r tool what; do
      printf '        %-24s %s\n' "$tool" "$what"
    done < <(cluster_tools "$key")
  done
}

# toggle_cluster N: tick or untick the Nth group on the screen.
toggle_cluster() {
  local entry key
  [[ "$1" =~ ^[0-9]+$ ]] || return 0
  local n=$((10#$1))   # base 10, so 08 is 8, not a bad octal number
  (( n >= 1 && n <= ${#CLUSTERS[@]} )) || return 0
  entry=${CLUSTERS[$((n - 1))]}
  key=${entry%%:*}
  if [[ "$key" == icons ]]; then
    if [[ "$GLYPHS" == on ]]; then GLYPHS=off; else GLYPHS=on; fi
  elif selected "$key"; then
    TOOLS=${TOOLS/,$key,/,}
  else
    TOOLS="$TOOLS$key,"
  fi
}

# ask_tools: the selection screen. Numbers tick and untick groups, Enter
# accepts. Sets and saves GLYPHS and TOOLS; it starts from the current answer
# (everything on a first run).
ask_tools() {
  local answer n entry key picked=""
  while :; do
    say "${BOLD}What to install${RESET}"
    note "Ghostty, herdr and terminal-notifier are always installed. Everything"
    note "else is up to you: an unticked group is neither installed nor set up."
    printf '\n'
    show_clusters
    printf '\n'
    printf '  %sNumbers to tick or untick (e.g. 7 8), Enter when done:%s ' "$BOLD" "$RESET"
    answer=""
    read -r answer || true
    [[ -n "$answer" ]] || break
    for n in $answer; do toggle_cluster "$n"; done
    printf '\n'
  done
  # Save in the screen's order, whatever order they were ticked in.
  for entry in "${CLUSTERS[@]}"; do
    key=${entry%%:*}
    [[ "$key" != icons ]] && selected "$key" && picked+="$key,"
  done
  TOOLS=",$picked"
  picked=${picked%,}
  choice_set GLYPHS "$GLYPHS"
  choice_set TOOLS "${picked:-none}"
  ok "icons: $GLYPHS · tools: ${picked:-none beyond Ghostty and herdr}"
  printf '\n'
}

# theme_name THEME: THEME as the choices summary says it.
theme_name() {
  case "$1" in
    dark) echo "always dark" ;;
    none) echo "left alone" ;;
    *) echo "follow macOS light/dark" ;;
  esac
}

# ask_theme: the colours question. Sets and saves THEME; Enter keeps the
# current answer (follow macOS on a first run).
ask_theme() {
  local current=1 answer
  case "$THEME" in dark) current=2 ;; none) current=3 ;; esac
  say "${BOLD}Colours${RESET}"
  note "Catppuccin in Ghostty, herdr, Neovim, yazi and bat."
  printf '\n'
  say "1) follow macOS light/dark  (suggested)"
  note "   Latte while macOS is light, Mocha while it's dark"
  say "2) always dark"
  note "   Mocha, whatever macOS is set to"
  say "3) leave my themes alone"
  note "   Ghostty and herdr get no theme. Neovim and yazi colours from"
  note "   an earlier run stay until --revert"
  printf '\n'
  printf '  %schoice [%s]:%s ' "$BOLD" "$current" "$RESET"
  answer=""
  read -r answer || true
  case "${answer:-$current}" in
    2) THEME=dark ;;
    3) THEME=none ;;
    *) THEME=auto ;;
  esac
  choice_set THEME "$THEME"
  ok "colours: $(theme_name "$THEME")"
  if [[ "$THEME" == auto ]]; then
    note "Ghostty, herdr, yazi and bat switch by themselves. A Neovim that's already"
    note "open may need a restart to repaint after macOS switches."
  fi
  printf '\n'
}

# ask_prompt: the prompt question, both prompts previewed in this folder
# first. Sets and saves PROMPT; Enter keeps the current answer (pure on a
# first run). tokyo night needs the Nerd Font, so it's only offered with icons.
ask_prompt() {
  local current=1 answer leave_opt=3
  [[ "$GLYPHS" == on ]] || leave_opt=2
  case "$(prompt_style)" in tokyo) current=2 ;; none) current=$leave_opt ;; esac
  say "${BOLD}Prompt${RESET}"
  note "Two prompts, both showing just the folder and the git branch:"
  printf '\n'
  say "1) pure"
  prompt_preview pure
  printf '\n'
  if [[ "$GLYPHS" == on ]]; then
    say "2) tokyo night"
    prompt_preview tokyo
    printf '\n'
  else
    note "(tokyo night needs the Nerd Font, and icons are off)"
    printf '\n'
  fi
  say "1) pure  (suggested)"
  [[ "$GLYPHS" == on ]] && say "2) tokyo night"
  say "$leave_opt) leave my prompt alone"
  printf '\n'
  printf '  %schoice [%s]:%s ' "$BOLD" "$current" "$RESET"
  answer=""
  read -r answer || true
  answer=${answer:-$current}
  if [[ "$answer" == "$leave_opt" ]]; then PROMPT=none
  elif [[ "$answer" == 2 ]]; then PROMPT=tokyo
  else PROMPT=pure
  fi
  choice_set PROMPT "$PROMPT"
  ok "prompt: $(prompt_name "$PROMPT")"
  printf '\n'
}

# ask_projects_dir: where the user keeps their repos. Sets and saves
# PROJECTS_DIR; Enter keeps the current answer.
ask_projects_dir() {
  local projects answer
  projects=$(current_projects_dir)
  say "${BOLD}Projects folder${RESET}"
  note "Where you keep your git repos. 'p' and herdr's prefix m search this folder."
  printf '  %sProjects folder%s %s[Enter keeps %s]%s ' "$BOLD" "$RESET" "$DIM" "$projects" "$RESET"
  read -r answer || true
  if [[ -n "$answer" ]]; then projects="${answer/#\~/$HOME}"; fi
  if [[ ! -d "$projects" ]]; then
    if confirm "$projects doesn't exist. Create it?"; then
      # Deliberately not journaled: it fills with the user's repos, and
      # --revert must never move those.
      mkdir -p "$projects"
    else
      warn "p and prefix m will find nothing until $projects exists"
    fi
  fi
  choice_set PROJECTS_DIR "$projects"
  printf '\n'
}

# choices_saved: true once every question in the choices stage has an answer.
choices_saved() {
  choice_get GLYPHS >/dev/null && choice_get TOOLS >/dev/null && choice_get TABS >/dev/null &&
    choice_get THEME >/dev/null &&
    { ! selected prompt || choice_get PROMPT >/dev/null; } &&
    { ! selected jumper || choice_get PROJECTS_DIR >/dev/null; }
}

# show_choices: last run's answers, one per line.
show_choices() {
  local tools=${TOOLS#,}
  tools=${tools%,}
  note "  icons            $GLYPHS"
  note "  tools            ${tools:-none beyond Ghostty and herdr}"
  note "  colours          $(theme_name "$THEME")"
  selected prompt && note "  prompt           $(prompt_name "$(prompt_style)")"
  selected jumper && note "  projects folder  $(current_projects_dir)"
  note "  default tabs     ${DEFAULT_TABS:-none, one plain tab}"
}

stage_choices() {
  say "Every question up front. The stages after this run from your answers, which"
  say "are saved in $CHOICES for re-runs and --only."
  say "Every later file change shows a diff first and keeps a backup in:"
  note "$BACKUP_DIR"
  printf '\n'
  if choices_saved; then
    say "Last time's answers:"
    show_choices
    printf '\n'
    if [[ "$YES" == 1 ]]; then
      ok "using them (--yes)"
      return 0
    fi
    if confirm "Use last time's answers?"; then
      return 0
    fi
    printf '\n'
  fi
  ask_tools
  ask_theme
  if selected prompt; then ask_prompt; fi
  if selected jumper; then ask_projects_dir; fi
  ask_default_tabs
}

# plan_gate: after the choices, the plan and the run's one confirmation.
# Returns 1 when the user says no. With no stage after choices in this run
# there is nothing to plan, so it only pauses. --yes shows the plan and goes.
plan_gate() {
  local entry later=false
  for entry in "${STAGES[@]}"; do
    [[ "${entry%%:*}" != choices ]] && stage_runs "${entry%%:*}" && later=true
  done
  if ! $later; then
    pause
    return 0
  fi
  show_plan
  printf '\n'
  [[ "$YES" == 1 ]] && return 0
  confirm "Go?" && return 0
  printf '\n'
  note "No files changed. Your answers are saved, so the next run can reuse them."
  return 1
}

# cluster_formulae KEY: the Homebrew formulae the group KEY brings. The Nerd
# Font is a cask, so the install stage handles icons itself.
cluster_formulae() {
  case "$1" in
    prompt) echo starship ;;
    jumper) echo fzf fd eza bat ;;
    typing) echo zsh-autosuggestions zsh-syntax-highlighting ;;
    editor) echo neovim tree-sitter-cli ripgrep fd ;;
    review) echo lazygit ;;
    files) echo yazi poppler resvg ;;
    github) echo gh ;;
    statusline) echo jq ;;
  esac
}

# stage_formulae SLUG: the Homebrew formulae the stage SLUG configures: the
# mandatory ones for herdr, else those of every selected group it configures.
stage_formulae() {
  local entry key
  if [[ "$1" == herdr ]]; then
    echo herdr terminal-notifier
    return 0
  fi
  for entry in "${CLUSTERS[@]}"; do
    key=${entry%%:*}
    [[ "${entry##*:}" == "$1" ]] && selected "$key" && cluster_formulae "$key"
  done
  return 0
}

# install_formulae: every formula the install stage brews, once each: those
# of every stage (so of every selected group) except the ones --skip names. --only and --from don't narrow it,
# so --only install installs everything.
install_formulae() {
  local entry slug f seen=" "
  for entry in "${STAGES[@]}"; do
    slug=${entry%%:*}
    [[ "$SKIP" == *",$slug,"* ]] && continue
    for f in $(stage_formulae "$slug"); do
      [[ "$seen" == *" $f "* ]] && continue
      seen+="$f "
      printf '%s\n' "$f"
    done
  done
}

# stage_tools NAME: install whatever the stage NAME needs that isn't there yet,
# for a stage run on its own (--only). Silent when the install stage did it.
stage_tools() {
  # shellcheck disable=SC2046 # one formula per word
  brew_formulae --quiet $(stage_formulae "$1")
}

# bat_themes: the Catppuccin themes BAT_THEME points at, unless already there.
bat_themes() {
  [[ "$THEME" != none ]] && selected jumper && command -v bat >/dev/null 2>&1 || return 0
  local dir flavour fetched=false
  dir="$(bat --config-dir)/themes"
  mkdir -p "$dir"
  for flavour in Mocha Latte; do
    [[ -f "$dir/Catppuccin $flavour.tmTheme" ]] && continue
    run curl -fsSL -o "$dir/Catppuccin $flavour.tmTheme" \
      "https://raw.githubusercontent.com/catppuccin/bat/main/themes/Catppuccin%20$flavour.tmTheme"
    fetched=true
  done
  if $fetched; then
    run bat cache --build
  else
    ok "Catppuccin themes for bat present"
  fi
}

stage_install() {
  say "Installs everything with Homebrew in one go. Tools you already have are left alone."
  note "Tip: don't press Cmd-D / Cmd-T while the wizard runs. They send herdr commands."
  printf '\n'
  if xcode-select -p >/dev/null 2>&1; then
    ok "Xcode command line tools present (Neovim needs a C compiler for syntax parsers)"
  else
    warn "Xcode command line tools missing. A macOS dialog will open."
    run xcode-select --install
    wait_for_user "Finish the install in that dialog, then press Enter"
  fi
  if [[ -d /Applications/Ghostty.app ]]; then
    ok "Ghostty already in /Applications"
  else
    run brew install --cask ghostty
  fi
  if [[ "$GLYPHS" != on ]]; then
    note "no Nerd Font needed with icons off"
  elif compgen -G "$HOME/Library/Fonts/JetBrainsMonoNerdFont*" >/dev/null; then
    ok "JetBrains Mono Nerd Font already installed"
  else
    run brew install --cask font-jetbrains-mono-nerd-font
  fi
  # shellcheck disable=SC2046 # one formula per word
  brew_formulae $(install_formulae)
  bat_themes
  pause
}

stage_ghostty() {
  local look check_colours=""
  case "$THEME" in
    auto) look="Catppuccin theme (light or dark with macOS)"
      check_colours=", and colours are Catppuccin (Latte while macOS is light, Mocha while dark)" ;;
    dark) look="Catppuccin Mocha theme (always dark)"
      check_colours=", and colours are Catppuccin (dark mauve/pink tones)" ;;
    none) look="Ghostty's own colours" ;;
  esac
  say "Font, $look, Option-as-Alt, quick terminal,"
  say "and Cmd shortcuts that drive herdr."
  write_ghostty_config
  if [[ "$GLYPHS" != on ]]; then
    note "icons are off, so Ghostty keeps its built-in font"
  elif "$GHOSTTY_BIN" +list-fonts 2>/dev/null | grep "JetBrainsMono Nerd Font" >/dev/null; then
    ok "Ghostty can see JetBrainsMono Nerd Font"
  else
    warn "Ghostty doesn't list 'JetBrainsMono Nerd Font' yet. It may appear after Ghostty restarts."
  fi
  local wanted=() name themes
  case "$THEME" in
    auto) wanted=("Catppuccin Mocha" "Catppuccin Latte") ;;
    dark) wanted=("Catppuccin Mocha") ;;
  esac
  themes=$("$GHOSTTY_BIN" +list-themes 2>/dev/null || true)
  for name in ${wanted[@]+"${wanted[@]}"}; do
    if grep -q "$name" <<<"$themes"; then
      ok "Ghostty has the '$name' theme"
    else
      warn "Couldn't confirm the '$name' theme name. Check with: ghostty +list-themes"
    fi
  done
  printf '\n'
  say "Every new Ghostty window (launch, Dock click, Cmd-N, quick terminal) follows one rule:"
  note "  herdr not open in any window   → the window attaches herdr"
  note "  herdr already open elsewhere   → plain shell. So Cmd-N is your 'without herdr' shortcut"
  note "  detach herdr with prefix q     → the window stays open as a plain shell; type herdr to go back"
  printf '\n'
  if ! in_ghostty; then
    say "The rest of the setup needs to run inside Ghostty so you can check how it looks."
    open -a Ghostty || warn "couldn't open Ghostty; open it from /Applications"
    local yes=""
    [[ "$YES" == 1 ]] && yes=" --yes"
    printf 'bash %q%s --from ghostty' "$SCRIPT_PATH" "$yes" | pbcopy
    step "If macOS asks whether to open Ghostty, click Open."
    step "In the Ghostty window, press Cmd-V then Enter (the re-run command is on your clipboard):"
    note "bash $SCRIPT_PATH$yes --from ghostty"
    printf '\n'
    note "This window's part is done. You can close it."
    exit 0
  fi
  ok "Running inside Ghostty"
  step "Press Cmd-Shift-, (comma) to reload Ghostty's config."
  if [[ "$GLYPHS" != on ]]; then
    note "Icons are off, so there's no Nerd Font to check."
    [[ -n "$check_colours" ]] && step "Check: ${check_colours#, and }."
  else
    say "Check the icons below. You should see: React, TypeScript, git branch, folder, Node, Apple."
    printf '\n      %s    %s    %s    %s    %s    %s\n\n' \
      $'\xee\x9e\xba' $'\xee\x98\xa8' $'\xee\x9c\xa5' $'\xef\x81\xbb' $'\xee\x9c\x98' $'\xef\x85\xb9'
    step "Also check: text uses JetBrains Mono$check_colours."
    if ! confirm "Do all six icons render (no boxes or question marks)?"; then
      warn "Quit Ghostty fully (Cmd-Q), reopen it, and re-run. Fonts load at app start."
      SKIPPED+=("Nerd Font icons not rendering: restart Ghostty and check 'ghostty +list-fonts'")
    fi
  fi
  step "Try it: press Cmd-N. With herdr open here, the new window is a plain shell. Cmd-W closes it."
  note "Later, close every Ghostty window and click the Dock icon: it opens straight into herdr."
  pause
}

# free_ctrl_space: herdr's prefix needs Ctrl-Space, which macOS takes by default.
free_ctrl_space() {
  say "herdr's prefix is Ctrl-Space. macOS uses that key to switch keyboard input"
  say "source by default, which would swallow it."
  if ctrl_space_taken; then
    open_url "x-apple.systempreferences:com.apple.Keyboard-Settings.extension"
    step "Click 'Keyboard Shortcuts…'."
    step "Pick 'Input Sources' in the left list."
    step "Untick 'Select the previous input source' (^Space)."
    step "Untick 'Select next source in Input menu' (^⌥Space) too."
    step "Click Done."
    wait_for_user "Press Enter when done"
    if ctrl_space_taken; then
      warn "macOS still reports Ctrl-Space as taken. If you only have one input source it may not matter."
      SKIPPED+=("confirm Ctrl-Space is free: System Settings → Keyboard → Keyboard Shortcuts → Input Sources")
    else
      ok "Ctrl-Space is free"
      journal_manual "Turn 'Select the previous input source' (^Space) and 'Select next source in Input menu' (^⌥Space) back on: Keyboard → Keyboard Shortcuts → Input Sources" \
        "x-apple.systempreferences:com.apple.Keyboard-Settings.extension"
    fi
  else
    ok "Ctrl-Space is already free"
  fi
}

# prompt_name STYLE: STYLE as the prompt question and the choices summary say it.
prompt_name() {
  case "$1" in
    tokyo) echo "tokyo night" ;;
    none) echo "left alone" ;;
    *) echo "$1" ;;
  esac
}

stage_prompt() {
  local style; style=$(prompt_style)
  stage_tools prompt
  if [[ "$style" == none ]]; then
    say "starship is installed and ~/.zshrc starts it. Your prompt config is left alone:"
    note "~/.config/starship.toml if you have one, starship's own look if not."
    pause
    return 0
  fi
  say "The $(prompt_name "$style") prompt: just the folder and the git branch."
  if [[ "$PROMPT" != "$style" ]]; then
    note "tokyo night needs the Nerd Font and icons are off, so it's pure."
  fi
  install_file "$HOME/.config/starship.toml" < <(starship_config "$style")
  printf '\n'
  say "Preview (in this directory):"
  prompt_preview "$style"
  printf '\n'
  note "New shells use it. Tweak it in ~/.config/starship.toml (https://starship.rs/config)."
  pause
}

# eza_icons < content: pass content through, minus every eza --icons flag when
# the glyph switch is off.
eza_icons() {
  if [[ "$GLYPHS" == on ]]; then cat; else sed -E 's/ --icons=[a-z]+//g'; fi
}

# zshrc_block: the wizard's block in ~/.zshrc, with lines only for the
# selected tools.
zshrc_block() {
  cat <<'EOF'
# Ghostty shell integration for plain shells. Ghostty starts windows through
# ghostty-launch, so it can't inject this itself. Skipped inside herdr panes.
if [[ -n "${GHOSTTY_RESOURCES_DIR:-}" && -z "${HERDR_ENV:-}" ]]; then
  builtin source "$GHOSTTY_RESOURCES_DIR/shell-integration/zsh/ghostty-integration"
fi

HISTFILE=~/.zsh_history HISTSIZE=50000 SAVEHIST=50000
setopt share_history hist_ignore_all_dups
EOF
  if selected prompt; then
    printf '\n%s\n' "(( \$+commands[starship] )) && eval \"\$(starship init zsh)\""
  fi
  if selected jumper; then
    eza_icons <<'EOF'

if (( $+commands[fzf] )); then
  source <(fzf --zsh)   # Ctrl-R history, Ctrl-T files, Alt-C cd
  export FZF_DEFAULT_COMMAND='fd --hidden --exclude .git'
  export FZF_CTRL_T_COMMAND="$FZF_DEFAULT_COMMAND"
  export FZF_CTRL_T_OPTS="--preview 'bat --color=always --style=numbers --line-range=:300 {}'"
  export FZF_ALT_C_COMMAND='fd --type d --hidden --exclude .git'
fi

# Human-friendly replacements. Claude Code (CLAUDECODE=1) snapshots aliases into
# its own shell, where eza/bat would break flags like `ls -lt` or `cat -v`.
if [[ -z "${CLAUDECODE:-}" ]]; then
  alias ls='eza --icons=auto --group-directories-first'
  alias ll='eza -la --icons=auto --group-directories-first --git'
  alias lt='eza --tree --level=2 --icons=auto --git-ignore'
  alias cat='bat --paging=never'
fi
alias keys='bat --paging=always --style=plain ~/.config/ghostty-herdr-cheatsheet.md'

# p: fuzzy-jump into a project directory
p() { local d; d=$(hproj --print) && [[ -n "$d" ]] && cd "$d"; }
EOF
  else
    printf '\n%s\n' "alias keys='less ~/.config/ghostty-herdr-cheatsheet.md'"
  fi
  selected editor && printf '%s\n' "alias v='nvim'"
  selected review && printf '%s\n' "alias lg='lazygit'"
  printf '%s\n' "alias gd='git diff'"
  if selected files; then
    cat <<'EOF'

# y: browse files with yazi; the shell follows you into the last directory
y() {
  local tmp cwd
  tmp="$(mktemp -t yazi-cwd.XXXXXX)"
  yazi "$@" --cwd-file="$tmp"
  IFS= read -r -d '' cwd < "$tmp"
  [[ -n "$cwd" && "$cwd" != "$PWD" ]] && builtin cd -- "$cwd"
  rm -f -- "$tmp"
}
EOF
  fi
  if selected typing; then
    cat <<'EOF'

_brew="${HOMEBREW_PREFIX:-/opt/homebrew}/share"
[[ -r $_brew/zsh-autosuggestions/zsh-autosuggestions.zsh ]] && source $_brew/zsh-autosuggestions/zsh-autosuggestions.zsh
# syntax highlighting must load last
[[ -r $_brew/zsh-syntax-highlighting/zsh-syntax-highlighting.zsh ]] && source $_brew/zsh-syntax-highlighting/zsh-syntax-highlighting.zsh
unset _brew
EOF
  fi
  return 0
}

# hproj_script: the project picker behind `p` and herdr's prefix m.
hproj_script() {
  eza_icons <<'EOF'
#!/usr/bin/env bash
# hproj: fuzzy-pick a project and open it as a herdr workspace.
#   hproj          create and focus a herdr workspace for the project
#   hproj --print  only print the chosen path (used by the `p` shell function)
set -euo pipefail
export PATH="/opt/homebrew/bin:/usr/local/bin:$HOME/.local/bin:$PATH"
root="${PROJECTS_DIR:-$HOME/code}"
choice=$(
  {
    fd --type d --max-depth 1 . "$root"
    fd --hidden --no-ignore --type d --max-depth 4 --exclude node_modules '^\.git$' "$root" --exec dirname {}
  } | sed -e 's:/*$::' -e "s:^$root/::" | sort -u |
    fzf --prompt='project › ' --preview "eza --tree --level=2 --icons=always --color=always --git-ignore '$root'/{}"
) || exit 0
dir="$root/$choice"
if [[ "${1:-}" == "--print" ]]; then
  printf '%s\n' "$dir"
else
  herdr workspace create --cwd "$dir" --label "$(basename "$dir")" --focus >/dev/null
fi
EOF
}

# zprofile_block PROJECTS_LINE: the wizard's block in ~/.zprofile, with lines
# only for the selected tools. PROJECTS_LINE is the projects folder as written
# there.
zprofile_block() {
  printf '%s\n' 'export PATH="$HOME/.local/bin:$PATH"'
  selected editor && printf '%s\n' 'export EDITOR=nvim VISUAL=nvim'
  if selected jumper; then
    printf 'export PROJECTS_DIR="%s"\n' "$1"
    case "$THEME" in
      # auto:system asks macOS, so bat is right in fzf's preview too, where it
      # can't ask the terminal.
      auto) printf '%s\n' 'export BAT_THEME="auto:system"' \
        'export BAT_THEME_DARK="Catppuccin Mocha"' 'export BAT_THEME_LIGHT="Catppuccin Latte"' ;;
      dark) printf '%s\n' 'export BAT_THEME="Catppuccin Mocha"' ;;
    esac
  fi
  return 0
}

stage_shell() {
  if selected jumper; then
    say "Project jumper: p (and herdr prefix m) fuzzy-finds a repo. fzf adds Ctrl-R history,"
    say "Ctrl-T files and Alt-C cd; eza is ls with git status; bat is cat with syntax colours."
  fi
  if selected typing; then
    say "Typing help: suggestions from your history, and commands coloured as you type."
  fi
  say "Adds a marked block to ~/.zprofile and ~/.zshrc. Your existing lines stay as they are."
  if selected jumper; then
    note "Aliases like ls→eza and cat→bat are skipped inside Claude Code's shell, so agents"
    note "get the real commands and their flags."
  fi
  printf '\n'
  stage_tools shell
  bat_themes
  local projects
  local projects_line=""
  if selected jumper; then
    projects=$(current_projects_dir)
    if [[ -d "$projects" ]]; then
      ok "projects folder: $projects"
    else
      warn "p and prefix m will find nothing until $projects exists (change it: --only choices,shell)"
    fi
    if [[ "$projects" == "$HOME"/* ]]; then
      projects_line="\$HOME${projects#"$HOME"}"
    else
      projects_line="$projects"
    fi
    export PROJECTS_DIR="$projects"
  fi
  printf '\n'
  upsert_block "$HOME/.zprofile" < <(zprofile_block "$projects_line")
  upsert_block "$HOME/.zshrc" < <(zshrc_block)
  if selected jumper; then
    install_file "$HOME/.local/bin/hproj" < <(hproj_script)
    chmod +x "$HOME/.local/bin/hproj"
  fi
  install_file "$CHEATSHEET" < <(cheatsheet)
  note "New shells pick this up. This wizard's own shell doesn't need it."
  pause
}

# lazygit_config: lazygit's config.yml. Nerd Font icons only with the glyph
# switch on.
lazygit_config() {
  cat <<'EOF'
# lazygit config, written by ghostty-herdr-wizard.sh
# Reference: https://github.com/jesseduffield/lazygit/blob/master/docs/Config.md
gui:
EOF
  # "" is lazygit's own default: no icons.
  if [[ "$GLYPHS" == on ]]; then
    printf '  nerdFontsVersion: "3"\n'
  else
    printf '  nerdFontsVersion: ""\n'
  fi
  cat <<'EOF'
os:
  editPreset: nvim
EOF
}

stage_review() {
  say "herdr-hunk: review the agent's diff hunk by hunk, comment on lines, and send the"
  say "comments back to the agent that wrote it. prefix Shift-H opens it; so does tab 4."
  say "lazygit: a full git UI. Stage single lines or hunks, commit, rebase, resolve conflicts."
  note "Opens with herdr prefix then d, or lg in any shell."
  stage_tools review
  printf '\n'
  install_file "$(lazygit_dir)/config.yml" < <(lazygit_config)
  printf '\n'
  install_hunk
  pause
}

# hunk_ready: true if the review stage sets up herdr-hunk: the review group is
# selected and Node is new enough.
hunk_ready() { selected review && node_ok; }

# hunk_config: herdr-hunk's own config. "overlay" opens a review over the
# focused pane instead of beside it, so tab 4's review fills that tab.
hunk_config() {
  cat <<'EOF'
# herdr-hunk config, written by ghostty-herdr-wizard.sh
# Reference: https://github.com/jhochenbaum/herdr-hunk-diff#configuration
[review]
placement = "overlay"
EOF
}

# hunk_config_dir: herdr-hunk's config folder, also before it is installed.
hunk_config_dir() {
  local dir
  dir=$(herdr plugin config-dir "$HUNK_ID" 2>/dev/null) || dir=""
  [[ -n "$dir" ]] || dir="$HOME/.config/herdr/plugins/config/$HUNK_ID"
  printf '%s' "$dir"
}

# install_hunk: herdr-hunk, its keybindings and its config, if Node allows.
#
# Its setup-keys writes the keys into herdr's config.toml, which the herdr stage
# owns as a whole file. So the herdr config already leaves prefix+shift+a free
# for it, the plugin writes its own binding syntax, and the result is journaled
# as the wizard's new baseline: a re-run's herdr_config carries the keys over
# unchanged, and --revert neither blames the user for them nor loses the
# pre-wizard original.
install_hunk() {
  local gate plugins
  if ! gate=$(node_gate); then
    warn "herdr-hunk skipped: it $(head -n1 <<< "$gate")"
    note "  $(sed -n 2p <<< "$gate" | sed 's/^ *//')"
    note "then: bash $SCRIPT_PATH --only review"
    [[ -n "$DEFAULT_TABS" ]] && note "tab 4 stays a plain shell for now"
    SKIPPED+=("herdr-hunk needs Node $NODE_MIN+. Upgrade it, then: bash $SCRIPT_PATH --only review")
    return 0
  fi
  # Captured first: under pipefail, grep -q quitting early could SIGPIPE herdr.
  plugins=$(herdr plugin list 2>/dev/null) || plugins=""
  if [[ "$plugins" == *"$HUNK_ID"* ]]; then
    ok "herdr-hunk already installed"
    journal_plugin "$HUNK_ID" pre-existing
  else
    cmd "herdr plugin install $HUNK_REPO"
    # The plugin builds with node from PATH: the one node_gate checked.
    if PATH="$USER_PATH:$PATH" herdr plugin install "$HUNK_REPO"; then
      journal_plugin "$HUNK_ID" new
    else
      warn "couldn't install herdr-hunk"
      SKIPPED+=("herdr-hunk: herdr plugin install $HUNK_REPO, then: bash $SCRIPT_PATH --only review")
      return 0
    fi
  fi

  cmd "herdr plugin action invoke setup-keys --plugin $HUNK_ID"
  # The plugin copies the config to config.toml.hunkdiff-backup before writing,
  # so that file is tracked too.
  if track_file "$HERDR_CONFIG.hunkdiff-backup" \
    track_file "$HERDR_CONFIG" herdr plugin action invoke setup-keys --plugin "$HUNK_ID"; then
    ok "herdr-hunk keys: prefix Shift-H review, Shift-S send, Shift-C last commit, Shift-A staged"
  else
    warn "herdr-hunk couldn't add its keys"
    SKIPPED+=("herdr-hunk keys: herdr plugin action invoke setup-keys --plugin $HUNK_ID")
  fi

  if [[ -n "$DEFAULT_TABS" ]]; then
    install_file "$(hunk_config_dir)/config.toml" < <(hunk_config)
  fi

  journal_undo undo_herdr
  if herdr server reload-config >/dev/null 2>&1; then
    ok "herdr reloaded its config"
  else
    note "herdr isn't running; it picks up the new keys when it next starts"
  fi
}

stage_github() {
  say "gh-dash lists your PRs, review requests and issues in the terminal. Opens with"
  say "herdr prefix then i. Press d on a PR to see its diff, c to comment."
  stage_tools github
  if gh auth status >/dev/null 2>&1; then
    ok "gh is already logged in"
  else
    say "gh will print a one-time code and open github.com in your browser."
    step "Copy the code, press Enter, paste it on the GitHub page, click Authorize."
    step "If asked 'Authenticate Git with your GitHub credentials?': Yes lets git push over HTTPS"
    step "through gh. Answer No if you already use SSH keys or another credential helper."
    wait_for_user "Press Enter to start the login"
    run gh auth login --hostname github.com --git-protocol https --web
  fi
  if gh extension list 2>/dev/null | grep 'gh-dash' >/dev/null; then
    ok "gh-dash already installed"
  else
    run gh extension install dlvhdr/gh-dash
  fi
  pause
}

# clone_lazyvim_starter DIR: the LazyVim starter config, as the user's own (no .git).
clone_lazyvim_starter() {
  git clone --depth 1 https://github.com/LazyVim/starter "$1" && rm -rf "$1/.git"
}

# nvim_icons_plugin: LazyVim's icon provider, set by the glyph switch. Written
# either way, so switching back to icons later undoes the ASCII fallback.
nvim_icons_plugin() {
  if [[ "$GLYPHS" == on ]]; then
    cat <<'EOF'
-- File and folder icons: "glyph" needs a Nerd Font, "ascii" works in any font.
-- Written by ghostty-herdr-wizard.sh from its Nerd Font + icons choice.
return {
  { "nvim-mini/mini.icons", opts = { style = "glyph" } },
}
EOF
    return 0
  fi
  cat <<'EOF'
-- Plain text: no Nerd Font. Written by ghostty-herdr-wizard.sh from its
-- Nerd Font + icons choice; re-run the wizard with icons on to undo.
--
-- LazyVim's own icons (diagnostics, git signs, completion kinds) are replaced
-- one by one. The kind names are LazyVim's at the time of writing; a kind it
-- adds later keeps its glyph.
local kinds = {}
for _, kind in ipairs({
  "Array", "Boolean", "Class", "Codeium", "Color", "Control", "Collapsed",
  "Constant", "Constructor", "Copilot", "Enum", "EnumMember", "Event", "Field",
  "File", "Folder", "Function", "Interface", "Key", "Keyword", "Method",
  "Module", "Namespace", "Null", "Number", "Object", "Operator", "Package",
  "Property", "Reference", "Snippet", "String", "Struct", "Supermaven",
  "TabNine", "Text", "TypeParameter", "Unit", "Value", "Variable",
}) do
  kinds[kind] = ""
end

return {
  { "nvim-mini/mini.icons", opts = { style = "ascii" } },
  {
    "LazyVim/LazyVim",
    opts = {
      icons = {
        misc = { dots = "..." },
        ft = { octo = "", gh = "", ["markdown.gh"] = "" },
        dap = {
          Stopped = { "> ", "DiagnosticWarn", "DapStoppedLine" },
          Breakpoint = "B ",
          BreakpointCondition = "C ",
          BreakpointRejected = { "R ", "DiagnosticError" },
          LogPoint = ".>",
        },
        diagnostics = { Error = "E ", Warn = "W ", Hint = "H ", Info = "I " },
        git = { added = "+ ", modified = "~ ", removed = "- " },
        kinds = kinds,
      },
    },
  },
  -- lualine's default separators are powerline glyphs.
  {
    "nvim-lualine/lualine.nvim",
    opts = { options = { component_separators = "|", section_separators = "" } },
  },
}
EOF
}

# nvim_colorscheme: LazyVim's colorscheme.lua for THEME, empty for "none"
# (LazyVim's own tokyonight).
nvim_colorscheme() {
  case "$THEME" in
    auto) cat <<'EOF'
-- Catppuccin: Latte when macOS is light, Mocha when it's dark, matching
-- Ghostty, herdr, bat and yazi. Neovim asks the terminal which one at startup.
return {
  {
    "catppuccin/nvim",
    name = "catppuccin",
    opts = { flavour = "auto", background = { light = "latte", dark = "mocha" } },
  },
  { "LazyVim/LazyVim", opts = { colorscheme = "catppuccin" } },
}
EOF
      ;;
    dark) cat <<'EOF'
-- Catppuccin Mocha, fixed dark to match Ghostty, herdr, bat and yazi.
return {
  { "LazyVim/LazyVim", opts = { colorscheme = "catppuccin-mocha" } },
}
EOF
      ;;
  esac
}

stage_editor() {
  say "LazyVim with TypeScript, Tailwind, ESLint, Prettier, JSON and Markdown support,"
  say "tuned for working next to agents: auto-reload of changed files and Diffview for review."
  note "Other languages (Python, Go, Rust, …): run :LazyExtras inside Neovim and press x to enable."
  stage_tools editor
  local nvim_dir="$HOME/.config/nvim" fresh=false
  local lazy_lua="$nvim_dir/lua/config/lazy.lua"
  if [[ -f "$lazy_lua" ]] && grep -q 'LazyVim/LazyVim' "$lazy_lua"; then
    ok "LazyVim config already present"
  else
    if [[ -e "$nvim_dir" ]]; then
      warn "$nvim_dir exists but isn't LazyVim."
      if confirm "Move it to the backup folder and install LazyVim?"; then
        replace_dir "$nvim_dir" run clone_lazyvim_starter "$nvim_dir" && fresh=true
      fi
    else
      replace_dir "$nvim_dir" run clone_lazyvim_starter "$nvim_dir" && fresh=true
    fi
  fi
  if [[ ! -f "$lazy_lua" ]]; then
    SKIPPED+=("LazyVim not installed")
    pause
    return 0
  fi

  local extras='    { import = "lazyvim.plugins.extras.lang.typescript" },
    { import = "lazyvim.plugins.extras.lang.tailwind" },
    { import = "lazyvim.plugins.extras.lang.json" },
    { import = "lazyvim.plugins.extras.lang.markdown" },
    { import = "lazyvim.plugins.extras.linting.eslint" },
    { import = "lazyvim.plugins.extras.formatting.prettier" },'
  if grep -q 'extras.lang.typescript' "$lazy_lua"; then
    ok "language extras already enabled"
  else
    EXTRAS="$extras" awk '{print} /import = "lazyvim.plugins" }/ && !done {print ENVIRON["EXTRAS"]; done=1}' \
      "$lazy_lua" > "$lazy_lua.new"
    if grep -q 'extras.lang.typescript' "$lazy_lua.new"; then
      install_file "$lazy_lua" < "$lazy_lua.new"
    else
      warn "couldn't find where to add extras in lazy.lua; add them later with :LazyExtras"
      SKIPPED+=("enable LazyVim extras with :LazyExtras (typescript, tailwind, eslint, prettier)")
    fi
    rm -f "$lazy_lua.new"
  fi

  local colorscheme; colorscheme=$(nvim_colorscheme)
  [[ -n "$colorscheme" ]] && install_file "$nvim_dir/lua/plugins/colorscheme.lua" <<<"$colorscheme"
  install_file "$nvim_dir/lua/plugins/icons.lua" < <(nvim_icons_plugin)
  install_file "$nvim_dir/lua/plugins/diffview.lua" <<'EOF'
-- Review everything an agent changed: file list on the left, before/after on the right.
return {
  {
    "sindrets/diffview.nvim",
    cmd = { "DiffviewOpen", "DiffviewClose", "DiffviewFileHistory" },
    keys = {
      { "<leader>gv", "<cmd>DiffviewOpen<cr>", desc = "Review changes (Diffview)" },
      { "<leader>gV", "<cmd>DiffviewClose<cr>", desc = "Close Diffview" },
      { "<leader>gH", "<cmd>DiffviewFileHistory %<cr>", desc = "File history (Diffview)" },
    },
  },
}
EOF
  upsert_block "$nvim_dir/lua/config/autocmds.lua" "--" <<'EOF'
-- Reload files that an agent changed on disk. LazyVim only checks when the
-- terminal regains focus, which doesn't happen when you switch herdr panes.
vim.o.autoread = true
local agent_reload = vim.uv.new_timer()
agent_reload:start(1000, 1000, vim.schedule_wrap(function()
  if vim.fn.mode() == "n" and vim.fn.getcmdwintype() == "" then
    vim.cmd("silent! checktime")
  end
end))
vim.api.nvim_create_autocmd({ "BufEnter", "CursorHold" }, {
  group = vim.api.nvim_create_augroup("agent_reload", { clear = true }),
  command = "silent! checktime",
})
EOF

  say "Downloading plugins (takes a minute or two)..."
  run nvim --headless "+Lazy! sync" +qa
  if $fresh; then
    printf '\n'
    step "Open a new Ghostty window (Cmd-N), run  p  to jump into one of your repos, then  nvim"
    step "Wait while Mason installs language servers (progress shows bottom right)."
    step "Press Space and pause: a menu of every command appears."
    step "Try Space Space (find file), Space / (search text), then gd on a symbol (go to definition)."
    step "Quit with :qa"
    wait_for_user "Press Enter when Neovim opened cleanly"
  else
    pause
  fi
}

