    dark) printf '[flavor]\ndark = "catppuccin-mocha"\nlight = "catppuccin-mocha"\n' ;;
  esac
  [[ "$GLYPHS" == on ]] && return 0
  [[ "$THEME" == none ]] || printf '\n'
  cat <<'EOF'
# Plain text: every glyph in yazi's default theme, replaced.
[tabs]
sep_inner = { open = "[", close = "]" }
sep_outer = { open = "", close = "" }

[indicator]
padding = { open = "", close = "" }

[status]
